# ---------- load raw .xls and fix peak-count anomalies ----------
load_and_fix_peaks <- function(filepath) {
  df <- as.data.frame(read_xls(filepath))
  df[["Sample weight"]] <- df[["Identifier 2"]]
  df[["Identifier 2"]] <- NA
  results <- list()
  df_many_peaks <- df[0, ]; df_few_peaks <- df[0, ]; df_zero_peaks <- df[0, ]
  for (row_id in unique(df$Row)) {
    df_subset <- df[df$Row == row_id, ]
    original_row_count <- nrow(df_subset)
    if (nrow(df_subset) > 6) {
      df_many_peaks <- rbind(df_many_peaks, df_subset)
      df_subset <- df_subset[df_subset[["d 13C/12C"]] <= 5, ]
      removed_count <- original_row_count - nrow(df_subset)
      comment <- paste(6 + removed_count, "peaks in total")
      if (nrow(df_subset) >= 6) df_subset[6, "Identifier 2"] <- comment
    }
    if (nrow(df_subset) == 4) {
      df_few_peaks <- rbind(df_few_peaks, df_subset)
      df_subset <- rbind(df_subset[1:3, ], df_subset[4, ], df_subset[4, ], df_subset[4, ])
      df_subset[6, "Identifier 2"] <- "4 peaks in total"
    } else if (nrow(df_subset) == 5) {
      df_few_peaks <- rbind(df_few_peaks, df_subset)
      df_subset <- rbind(df_subset[1:3, ], df_subset[3, ], df_subset[4:5, ])
      df_subset[6, "Identifier 2"] <- "5 peaks in total"
    } else if (nrow(df_subset) == 3) {
      df_few_peaks <- rbind(df_few_peaks, df_subset)
      df_zero_peaks <- rbind(df_zero_peaks, df_subset)
      df_subset <- rbind(df_subset[1:3, ], df_subset[3, ], df_subset[3, ], df_subset[3, ])
      df_subset[6, "Identifier 2"] <- "No sample peaks"
    }
    results[[as.character(row_id)]] <- df_subset
  }
  outlier  <- unique(df_many_peaks$Row)
  outlier2 <- unique(df_few_peaks$Row)
  outlier3 <- unique(df_zero_peaks$Row)
  df <- do.call(rbind, results)
  df$Peak <- rep(1:6, nrow(df) / 6)
  i <- 6 * (1:350)
  df_subset <- df[i, ][rowSums(is.na(df[i, ])) != ncol(df[i, ]), ]
  colnames(df_subset)[14] <- "d 18O/16O(SMOW)"
  list(df_subset = df_subset, outlier = outlier, outlier2 = outlier2, outlier3 = outlier3)
}

# ---------- split International / Inhouse / Sample ----------
format_data <- function(df_subset) {
  df_subset[["Identifier 1"]] <- gsub(" ", "", toupper(df_subset[["Identifier 1"]]))
  International_df <- df_subset[grepl("NBS18|NBS19|LSVEC", df_subset[["Identifier 1"]]), ]
  Mass_df <- df_subset[grepl("STD", df_subset[["Identifier 1"]]), , drop = FALSE]
  Sample_df <- df_subset[!grepl("STD", df_subset[["Identifier 1"]]) &
    !grepl("NBS18|NBS19|LSVEC", df_subset[["Identifier 1"]]), , drop = FALSE]
  list(International_df = International_df, Mass_df = Mass_df, Sample_df = Sample_df)
}

attach_true_intl <- function(df, std_values) {
  df[["True d 13C/12C"]] <- NA_real_
  df[["True d 18O/16O(SMOW)"]] <- NA_real_
  i1 <- df[["Identifier 1"]]
  df[["True d 13C/12C"]][grepl("NBS18", i1)] <- std_values$NBS18C
  df[["True d 13C/12C"]][grepl("NBS19", i1)] <- std_values$NBS19C
  df[["True d 13C/12C"]][grepl("LSVEC", i1)] <- std_values$LSVECC
  df[["True d 18O/16O(SMOW)"]][grepl("NBS18", i1)] <- std_values$NBS18O
  df[["True d 18O/16O(SMOW)"]][grepl("NBS19", i1)] <- std_values$NBS19O
  df[["True d 18O/16O(SMOW)"]][grepl("LSVEC", i1)] <- std_values$LSVECO
  df
}

