# Rmd QA: comments + Possibly bad sample; blank zero-peak rows
annotate_sample_qa <- function(Sample_df, outlier = integer(0),
                               outlier2 = integer(0), outlier3 = integer(0)) {
  if (is.null(Sample_df) || nrow(Sample_df) == 0) return(Sample_df)
  if (!"Comment" %in% names(Sample_df)) {
    Sample_df[["Comment"]] <- if ("Identifier 2" %in% names(Sample_df))
      Sample_df[["Identifier 2"]] else NA_character_
  }
  id1 <- Sample_df[["Identifier 1"]]
  is_blank <- toupper(as.character(id1)) %in% c("BLANK", "NA", "")
  area <- Sample_df[["Area All"]]
  d13 <- Sample_df[["d 13C/12C"]]
  low_area <- !is.na(area) & area < 4
  very_neg <- !is.na(d13) & d13 < -5
  Sample_df[["Comment"]] <- ifelse(low_area, "Area very low, check sample",
                                   Sample_df[["Comment"]])
  Sample_df[["Comment"]] <- ifelse(
    !is_blank & very_neg,
    ifelse(is.na(Sample_df[["Comment"]]) | Sample_df[["Comment"]] == "",
           "Isotopic ratio very negative",
           paste(Sample_df[["Comment"]], "Carbon isotopic ratio very negative", sep = "; ")),
    Sample_df[["Comment"]]
  )
  zero_rows <- Sample_df$Row %in% outlier3
  if (any(zero_rows)) {
    blank_cols <- intersect(c(
      "Area All", "d 13C/12C", "International corrected d 13C/12C",
      "Mass corrected d 13C/12C", "Drift corrected d 13C/12C", "AT% 13C/12C",
      "Sample Dilution", "d 18O/16O(SMOW)",
      "International corrected d 18O/16O(SMOW)", "Mass corrected d 18O/16O(SMOW)",
      "Drift corrected d 18O/16O(SMOW)", "Drift corrected d 18O/16O(PDB)",
      "R 18O/16O", "AT% 18O/16O", "Time", "Sample weight"
    ), names(Sample_df))
    Sample_df[zero_rows, blank_cols] <- NA
    Sample_df[["Comment"]][zero_rows] <- "No sample peak"
  }
  Sample_df[["Possibly bad sample"]] <- as.integer(
    !is_blank & (
      low_area | very_neg |
        Sample_df$Row %in% outlier |
        Sample_df$Row %in% outlier2
    )
  )
  Sample_df
}

# Rmd-style: move outliers to bottom, blank corrected cols, comment if empty.
# When outlier_C / outlier_O / outlier_N exist, blank only that isotope's cols.
finalize_std_export <- function(df, corrected_cols) {
  if (is.null(df) || nrow(df) == 0) return(df)
  if (!"Comment" %in% names(df)) {
    df[["Comment"]] <- if ("Identifier 2" %in% names(df))
      as.character(df[["Identifier 2"]]) else NA_character_
  }
  blank <- intersect(corrected_cols, names(df))
  has_dual <- any(c("outlier_C", "outlier_O", "outlier_N") %in% names(df))
  if (has_dual) {
    blank_flag <- function(flag, patterns) {
      if (!flag %in% names(df)) return(invisible(NULL))
      is_out <- df[[flag]] == "Yes"
      if (!any(is_out)) return(invisible(NULL))
      cols <- unique(unlist(lapply(patterns, function(p)
        grep(p, blank, value = TRUE))))
      if (length(cols)) df[is_out, cols] <<- NA
    }
    blank_flag("outlier_C", c("d 13C", "TrueC", "AT% 13C", "Measured-TrueC"))
    blank_flag("outlier_O", c("d 18O", "TrueO", "AT% 18O", "R 18O", "Measured-TrueO"))
    blank_flag("outlier_N", c("d 15N", "TrueN", "AT% 15N", "Measured-TrueN"))
    # Shared elemental / C/N if either C or N is out
    if ("outlier_C" %in% names(df) || "outlier_N" %in% names(df)) {
      out_cn <- rep(FALSE, nrow(df))
      if ("outlier_C" %in% names(df)) out_cn <- out_cn | df$outlier_C == "Yes"
      if ("outlier_N" %in% names(df)) out_cn <- out_cn | df$outlier_N == "Yes"
      cn_cols <- intersect(grep("C/N|µg C|µg N|%C|%N|N \\(sam\\)|C \\(sam\\)",
                                blank, value = TRUE), names(df))
      if (any(out_cn) && length(cn_cols)) df[out_cn, cn_cols] <- NA
    }
  } else if ("outlier" %in% names(df) && any(df$outlier == "Yes")) {
    df[df$outlier == "Yes", blank] <- NA
  }
  is_out <- if ("outlier" %in% names(df)) df$outlier == "Yes" else rep(FALSE, nrow(df))
  if (!any(is_out)) return(df)
  empty_cmt <- is.na(df[["Comment"]]) | trimws(as.character(df[["Comment"]])) == ""
  df[["Comment"]][is_out & empty_cmt] <- "Standard removed"
  rbind(df[!is_out, , drop = FALSE], df[is_out, , drop = FALSE])
}

