if (!exists("clear_embed_tmp", mode = "function", inherits = TRUE)) {
  clear_embed_tmp <- function() {
    if (length(.embed_tmp_env$files)) unlink(.embed_tmp_env$files)
    .embed_tmp_env$files <- character(0)
  }
}

if (!exists("plot_wb_scatter", mode = "function", inherits = TRUE)) {
  plot_wb_scatter <- function(df, xvar, yvar, title, xlabel, ylabel,
                              slope = NULL, intercept = NULL, r2 = NULL,
                              excl_flag = "outlier", include_outliers = TRUE) {
    df <- as.data.frame(df)
    if (is.null(df[["Plot ID"]])) {
      df[["Plot ID"]] <- if (!is.null(df[["Row number"]])) df[["Row number"]] else seq_len(nrow(df))
    }
    keep <- if (excl_flag %in% names(df)) df[df[[excl_flag]] != "Yes", , drop = FALSE] else df
    rem  <- if (include_outliers && excl_flag %in% names(df))
      df[df[[excl_flag]] == "Yes", , drop = FALSE] else df[0, ]
    p <- ggplot() + plot_theme + labs(title = title, x = xlabel, y = ylabel)
    if (nrow(keep) > 0) {
      p <- p +
        geom_point(data = keep, aes(x = .data[[xvar]], y = .data[[yvar]]), color = "black") +
        geom_smooth(data = keep, aes(x = .data[[xvar]], y = .data[[yvar]]),
                    method = "lm", se = FALSE, color = "blue", formula = y ~ x) +
        geom_text_repel(data = keep,
                        aes(x = .data[[xvar]], y = .data[[yvar]],
                            label = .data[["Plot ID"]]),
                        color = "black", size = 3.5, fontface = "bold",
                        max.overlaps = Inf, min.segment.length = 0,
                        box.padding = 0.35, point.padding = 0.25, seed = 1)
    }
    if (nrow(rem) > 0) {
      p <- p +
        geom_point(data = rem, aes(x = .data[[xvar]], y = .data[[yvar]]),
                   color = "red", size = 2.5) +
        geom_text_repel(data = rem,
                        aes(x = .data[[xvar]], y = .data[[yvar]],
                            label = .data[["Plot ID"]]),
                        color = "red", size = 3.5, fontface = "bold",
                        max.overlaps = Inf, min.segment.length = 0,
                        box.padding = 0.35, point.padding = 0.25, seed = 1)
    }
    if (!is.null(slope) && nrow(keep) > 0) {
      xr <- range(keep[[xvar]], na.rm = TRUE)
      yr <- range(keep[[yvar]], na.rm = TRUE)
      p <- p + annotate("text",
                        x = mean(xr), y = max(yr, na.rm = TRUE),
                        label = eq_label(slope, intercept, r2),
                        vjust = -0.6, size = 3)
    }
    p
  }
}

# ------------------------------------------------------------------
# True values / IDs (Rmd)
# ------------------------------------------------------------------
thermo_ea_true <- list(
  NBS18C = -5.014,
  CaffeineC = -27.771,
  CaffeineN = 1.00,
  N2 = 20.3,
  GelAC = -21.81,
  GelAN = 5.4
)

International_ID <- c("NBS18", "NBS 18", "CAFFEINE", "N2", "BLANK")
Mass_ID         <- c("GEL A", "GELA", "BLANK")
Sample_ID_std   <- c("NBS18", "NBS 18", "CAFFEINE", "N2", "GEL A", "GELA")
Blank_ID        <- c("BLANK")
NO_N            <- c("NBS18", "NBS 18")
NO_C            <- c("N2", "N 2")

# ------------------------------------------------------------------
# Port process_dataset / process_flash_tcd from Rmd Load data
# ------------------------------------------------------------------
process_dataset <- function(df) {
  unique_rows <- unique(df$Row)
  processed_list <- list()
  for (row_id in unique_rows) {
    subset_df <- df[df$Row == row_id, ]
    rows_10 <- !apply(subset_df[, 10, drop = FALSE], 1, function(x) all(is.na(x)))
    if (sum(rows_10) == 3) {
      row_to_add <- subset_df[1, ]
      new_row <- row_to_add
      subset_df <- rbind(subset_df[1, ], new_row, subset_df[2:nrow(subset_df), ])
      if (nrow(subset_df) >= 4 && !subset_df[4, "Identifier 1"] %in% c("BLANK", "NBS18", "NBS 18")) {
        subset_df[4, 4] <- "No N sample peak"
      }
    }
    rows_11 <- !apply(subset_df[, 11, drop = FALSE], 1, function(x) all(is.na(x)))
    if (sum(rows_11) == 2) {
      last_row <- subset_df[nrow(subset_df), ]
      new_row <- last_row
      subset_df <- rbind(subset_df, new_row)
      if (nrow(subset_df) >= 5 && !subset_df[5, "Identifier 1"] %in% c("BLANK", "N2", "N 2")) {
        subset_df[5, 4] <- "No C sample peak"
      }
    }
    if (sum(rows_11) > 3) {
      subset_df <- subset_df[!(rows_11 & subset_df$`Area All` < 1), ]
    }
    processed_list[[as.character(row_id)]] <- subset_df
  }
  do.call(rbind, processed_list)
}

process_flash_tcd <- function(df) {
  unique_rows <- unique(df$Row)
  processed_list <- list()
  for (row_id in unique_rows) {
    subset_df <- df[df$Row == row_id, ]
    above_150 <- any(subset_df$`Rt Flash TCD` >= 201 & subset_df$`Rt Flash TCD` <= 300, na.rm = TRUE)
    below_200 <- any(subset_df$`Rt Flash TCD` >= 100 & subset_df$`Rt Flash TCD` <= 200, na.rm = TRUE)
    has_na <- any(is.na(subset_df$`Rt Flash TCD`))
    create_new_row <- function(rt_value) {
      new_row <- subset_df[1, ]
      new_row[5:9] <- NA
      new_row$`Rt Flash TCD` <- rt_value
      new_row
    }
    if (!above_150) subset_df <- rbind(subset_df, create_new_row(227))
    if (!below_200) subset_df <- rbind(subset_df, create_new_row(126))
    if (!has_na)    subset_df <- rbind(subset_df, create_new_row(NA))
    subset_df <- subset_df[seq_len(min(3, nrow(subset_df))), ]
    processed_list[[as.character(row_id)]] <- subset_df
  }
  do.call(rbind, processed_list)
}

# N|C wide reshape (Rmd Formatting): odd rows = N peak, even = C peak
reshape_nc_pair <- function(df) {
  if (is.null(df) || nrow(df) == 0) {
    return(df[0, , drop = FALSE])
  }
  df1 <- df |>
    mutate(row_num = row_number()) |>
    filter(row_num %% 2 == 0) |>
    select(-row_num) |>
    select(-c(1:4, 7:10)) |>
    rename(`Sample Dilution C` = 1, `Area All C` = 2)
  df2 <- df |>
    mutate(row_num = row_number()) |>
    filter(row_num %% 2 != 0) |>
    select(-row_num) |>
    select(-c(11:15)) |>
    rename(`Sample Dilution N` = 5, `Area All N` = 6) |>
    mutate(across(3:10, ~ ifelse(`Identifier 1` == "BLANK", NA, .)))
  cbind(df2, df1)
}

na_mean <- function(x) {
  m <- mean(x, na.rm = TRUE)
  if (is.na(m)) 0 else m
}

# Rmd blank mass-balance (including quirks for which blank pool is used)
blank_correct_delta <- function(area, delta, blank_area, blank_delta) {
  ba <- na_mean(blank_area)
  bd <- na_mean(blank_delta)
  (area * delta - ba * bd) / (area - ba)
}

round_thermo_corrected <- function(df) {
  if (is.null(df) || !nrow(df)) return(df)
  dn <- decimal_places(df[["d 15N/14N"]], 3L)
  dc <- decimal_places(df[["d 13C/12C"]], 3L)
  # Round final / display isotope cols only — not raw or intermediate Blank corrected d*
  n_cols <- grep(
    "^(International|Mass|Drift) corrected d 15N|Measured-TrueN|Blank corrected-TrueN",
    names(df), value = TRUE)
  c_cols <- grep(
    "^(International|Mass|Drift) corrected d 13C|Measured-TrueC|Blank corrected-TrueC",
    names(df), value = TRUE)
  for (nm in n_cols) if (is.numeric(df[[nm]])) df[[nm]] <- round(df[[nm]], dn)
  for (nm in c_cols) if (is.numeric(df[[nm]])) df[[nm]] <- round(df[[nm]], dc)
  df
}

# ------------------------------------------------------------------
# Load + format raw Thermo EA .xls
# ------------------------------------------------------------------
load_thermo_ea <- function(path) {
  df <- as.data.frame(read_xls(path))
  df <- subset(df, !tolower(`Identifier 1`) %in% c("systemblank", "system blank"))
  df_TCD <- tryCatch(
    as.data.frame(read_xls(path, sheet = "TCD.wke")),
    error = function(e) NULL
  )
  if (!is.null(df_TCD)) {
    df_TCD <- subset(df_TCD, !tolower(`Identifier 1`) %in% c("systemblank", "system blank"))
  }

  df$`Sample Dilution` <- as.factor(df$`Sample Dilution`)
  df$`Identifier 1` <- toupper(as.character(df$`Identifier 1`))
  df <- df %>%
    mutate(`Identifier 2` = str_replace_all(as.character(`Identifier 2`), ",", "."),
           `Identifier 2` = as.numeric(`Identifier 2`))

  if (!is.null(df_TCD) && nrow(df_TCD) > 0) {
    df_TCD <- df_TCD %>%
      mutate(`Identifier 1` = toupper(as.character(`Identifier 1`)),
             `Identifier 2` = ifelse(`Identifier 1` == "BLANK", NA, `Identifier 2`),
             `Identifier 2` = str_replace_all(as.character(`Identifier 2`), ",", "."),
             `Identifier 2` = as.numeric(`Identifier 2`))
    df_TCD <- df_TCD[!duplicated(df_TCD), ]
    df_TCD <- process_flash_tcd(df_TCD)
  }

  df <- process_dataset(df)

  Manipulated_samples <- df %>%
    group_by(Row) %>%
    filter(any(Comment %in% c("No N sample peak", "No C sample peak"))) %>%
    ungroup()

  # Sample peaks only (Rmd index pattern: positions 4,5 of each 7-row block)
  n <- nrow(df)
  i <- sort(unique(c(seq(4L, n, by = 7L), seq(5L, n, by = 7L))))
  i <- i[i <= n]
  df_subset <- df[i, ][rowSums(is.na(df[i, ])) != ncol(df[i, ]), ]
  df_subset$`Identifier 1` <- gsub(" ", "", toupper(df_subset$`Identifier 1`))
  df_subset <- df_subset %>%
    group_by(Row) %>%
    mutate(CombinedComment = paste(na.omit(unique(Comment)), collapse = "; ")) %>%
    ungroup() %>%
    mutate(Comment = CombinedComment) %>%
    select(-CombinedComment)

  # Space-stripped IDs for matching
  intl_ids  <- c("NBS18", "CAFFEINE", "N2", "BLANK")
  mass_ids  <- c("GELA", "BLANK")
  sample_ex <- c("NBS18", "CAFFEINE", "N2", "GELA")

  International_df <- df_subset[df_subset$`Identifier 1` %in% intl_ids, , drop = FALSE]
  Mass_df          <- df_subset[df_subset$`Identifier 1` %in% mass_ids, , drop = FALSE]
  Sample_df        <- df_subset[!(df_subset$`Identifier 1` %in% sample_ex), , drop = FALSE]

  International_df <- reshape_nc_pair(International_df)
  Mass_df          <- reshape_nc_pair(Mass_df)
  Sample_df        <- reshape_nc_pair(Sample_df)

  tv <- thermo_ea_true

  # True values
  if (nrow(International_df) > 0) {
    International_df <- International_df %>%
      mutate(
        `True d 13C/12C` = NA_real_,
        `True d 15N/14N` = NA_real_
      )
    id1 <- International_df$`Identifier 1`
    International_df$`True d 13C/12C`[id1 %in% c("NBS18", "NBS 18")] <- tv$NBS18C
    International_df$`True d 13C/12C`[id1 == "CAFFEINE"] <- tv$CaffeineC
    International_df$`True d 15N/14N`[id1 %in% c("N2", "N 2")] <- tv$N2
    International_df$`True d 15N/14N`[id1 == "CAFFEINE"] <- tv$CaffeineN
    International_df$`True d 13C/12C`[id1 == "BLANK"] <- NA_real_
    International_df$`True d 15N/14N`[id1 == "BLANK"] <- NA_real_
  }

  if (nrow(Mass_df) > 0) {
    Mass_df <- Mass_df %>%
      mutate(
        `True d 13C/12C` = ifelse(`Identifier 1` == "BLANK", NA_real_, tv$GelAC),
        `True d 15N/14N` = ifelse(`Identifier 1` == "BLANK", NA_real_, tv$GelAN)
      )
  }

  # Split blanks (Rmd Blank outliers)
  International_df1 <- subset(International_df, `Identifier 1` == "BLANK")
  Mass_df1          <- subset(Mass_df, `Identifier 1` == "BLANK")
  rownames(International_df1) <- NULL
  rownames(Mass_df1) <- NULL
  # Default: keep all blanks (ij empty in Rmd)
  International_df2 <- International_df1
  Mass_df2          <- Mass_df1

  International_df <- subset(International_df, `Identifier 1` != "BLANK")
  Mass_df          <- subset(Mass_df, `Identifier 1` != "BLANK")
  rownames(International_df) <- NULL
  rownames(Mass_df) <- NULL

  # Blank correction (Rmd formulas, including quirks)
  if (nrow(International_df) > 0) {
    International_df <- International_df %>%
      mutate(
        `Blank corrected d 15N/14N` = blank_correct_delta(
          `Area All N`, `d 15N/14N`,
          International_df2$`Area All N`, International_df2$`d 15N/14N`),
        `Blank corrected d 13C/12C` = blank_correct_delta(
          `Area All C`, `d 13C/12C`,
          International_df2$`Area All C`, International_df2$`d 13C/12C`)
      )
    International_df$`Measured-TrueN` <-
      International_df$`Blank corrected d 15N/14N` - International_df$`True d 15N/14N`
    International_df$`Measured-TrueC` <-
      International_df$`Blank corrected d 13C/12C` - International_df$`True d 13C/12C`
    # Rmd also stores Blank corrected-True*
    International_df$`Blank corrected-TrueN` <- International_df$`Measured-TrueN`
    International_df$`Blank corrected-TrueC` <- International_df$`Measured-TrueC`

    # NO_N / NO_C: blank N or C cols for NBS18 / N2
    International_df <- International_df %>%
      mutate(
        across(any_of(c("Area All N", "d 15N/14N", "True d 15N/14N",
                        "Blank corrected d 15N/14N", "Measured-TrueN",
                        "Blank corrected-TrueN", "AT% 15N/14N")),
               ~ ifelse(`Identifier 1` %in% c("NBS18", "NBS 18"), NA, .)),
        across(any_of(c("Area All C", "d 13C/12C", "True d 13C/12C",
                        "Blank corrected d 13C/12C", "Measured-TrueC",
                        "Blank corrected-TrueC", "AT% 13C/12C")),
               ~ ifelse(`Identifier 1` %in% c("N2", "N 2"), NA, .))
      )
  }

  if (nrow(Mass_df) > 0) {
    # Rmd quirk: Mass C numerator uses Mass blank area*delta; denominator uses Intl blank Area C
    ba_n <- na_mean(Mass_df2$`Area All N`)
    bd_n <- na_mean(Mass_df2$`d 15N/14N`)
    ba_c_num <- na_mean(Mass_df2$`Area All C`)
    bd_c <- na_mean(Mass_df2$`d 13C/12C`)
    ba_c_den <- na_mean(International_df2$`Area All C`)
    Mass_df <- Mass_df %>%
      mutate(
        `Blank corrected d 15N/14N` = (`Area All N` * `d 15N/14N` - ba_n * bd_n) /
          (`Area All N` - ba_n),
        `Blank corrected d 13C/12C` = (`Area All C` * `d 13C/12C` - ba_c_num * bd_c) /
          (`Area All C` - ba_c_den)
      )
    Mass_df$`Measured-TrueN` <-
      Mass_df$`Blank corrected d 15N/14N` - Mass_df$`True d 15N/14N`
    Mass_df$`Measured-TrueC` <-
      Mass_df$`Blank corrected d 13C/12C` - Mass_df$`True d 13C/12C`
    Mass_df$`Blank corrected-TrueN` <- Mass_df$`Measured-TrueN`
    Mass_df$`Blank corrected-TrueC` <- Mass_df$`Measured-TrueC`
  }

  if (nrow(Sample_df) > 0) {
    # Rmd sample blank quirks: N from Mass_df2; C delta mean from Mass_df1,
    # C area denominator from International_df1
    Sample_df <- Sample_df %>%
      mutate(
        `Blank corrected d 15N/14N` = blank_correct_delta(
          `Area All N`, `d 15N/14N`,
          Mass_df2$`Area All N`, Mass_df2$`d 15N/14N`),
        `Blank corrected d 13C/12C` = (
          (`Area All C` * `d 13C/12C` -
             na_mean(Mass_df2$`Area All C`) * na_mean(Mass_df1$`d 13C/12C`)) /
            (`Area All C` - na_mean(International_df1$`Area All C`))
        )
      )
  }

  if (nrow(International_df) > 0) {
    International_df$outlier <- "No"
    International_df[["Row number"]] <- seq_len(nrow(International_df))
    International_df[["Plot ID"]] <- International_df[["Row number"]]
  }
  if (nrow(Mass_df) > 0) {
    Mass_df$outlier <- "No"
    Mass_df[["Row number"]] <- seq_len(nrow(Mass_df))
    Mass_df[["Plot ID"]] <- Mass_df[["Row number"]]
  }

  list(
    International_df = International_df,
    Mass_df = Mass_df,
    Sample_df = Sample_df,
    International_df1 = International_df1,
    International_df2 = International_df2,
    Mass_df1 = Mass_df1,
    Mass_df2 = Mass_df2,
    df_TCD = df_TCD,
    Manipulated_samples = Manipulated_samples,
    flags = list(
      manipulated_rows = unique(Manipulated_samples$Row),
      n_intl = nrow(International_df),
      n_mass = nrow(Mass_df),
      n_samp = nrow(Sample_df)
    )
  )
}

# ------------------------------------------------------------------
# Correction pipeline (fit on non-outliers; keep all rows for plots)
# ------------------------------------------------------------------
apply_thermo_ea_corrections <- function(loaded,
                                        exclude_intl = integer(0),
                                        exclude_mass = integer(0),
                                        exclude_intl_c = NULL, exclude_intl_n = NULL,
                                        exclude_mass_c = NULL, exclude_mass_n = NULL,
                                        blank_correct_n = FALSE) {
  tv <- thermo_ea_true
  GelAC <- tv$GelAC
  GelAN <- tv$GelAN

  International_df <- loaded$International_df
  Mass_df          <- loaded$Mass_df
  Sample_df        <- loaded$Sample_df
  Mass_df1         <- loaded$Mass_df1
  Mass_df2         <- loaded$Mass_df2
  International_df1 <- loaded$International_df1
  International_df2 <- loaded$International_df2
  df_TCD           <- loaded$df_TCD

  results <- list()
  results$blank_correct_n <- isTRUE(blank_correct_n)

  # Optional N blank correction (default off = passthrough, same as Sercon UI).
  # C always blank-corrected in load.
  apply_n_blank <- function(area, delta, blank_area, blank_delta) {
    if (isTRUE(blank_correct_n))
      blank_correct_delta(area, delta, blank_area, blank_delta)
    else
      as.numeric(delta)
  }
  if (nrow(International_df) > 0) {
    International_df$`Blank corrected d 15N/14N` <- apply_n_blank(
      International_df$`Area All N`, International_df$`d 15N/14N`,
      International_df2$`Area All N`, International_df2$`d 15N/14N`)
    International_df$`Measured-TrueN` <-
      International_df$`Blank corrected d 15N/14N` - International_df$`True d 15N/14N`
    International_df$`Blank corrected-TrueN` <- International_df$`Measured-TrueN`
    International_df$`Blank corrected d 15N/14N`[
      International_df$`Identifier 1` %in% c("NBS18", "NBS 18")] <- NA_real_
    International_df$`Measured-TrueN`[
      International_df$`Identifier 1` %in% c("NBS18", "NBS 18")] <- NA_real_
    International_df$`Blank corrected-TrueN`[
      International_df$`Identifier 1` %in% c("NBS18", "NBS 18")] <- NA_real_
  }
  if (nrow(Mass_df) > 0) {
    ba_n <- na_mean(Mass_df2$`Area All N`)
    bd_n <- na_mean(Mass_df2$`d 15N/14N`)
    if (isTRUE(blank_correct_n) && is.finite(ba_n) && is.finite(bd_n)) {
      Mass_df$`Blank corrected d 15N/14N` <-
        (Mass_df$`Area All N` * Mass_df$`d 15N/14N` - ba_n * bd_n) /
        (Mass_df$`Area All N` - ba_n)
    } else {
      Mass_df$`Blank corrected d 15N/14N` <- Mass_df$`d 15N/14N`
    }
    Mass_df$`Measured-TrueN` <-
      Mass_df$`Blank corrected d 15N/14N` - Mass_df$`True d 15N/14N`
    Mass_df$`Blank corrected-TrueN` <- Mass_df$`Measured-TrueN`
  }
  if (nrow(Sample_df) > 0) {
    Sample_df$`Blank corrected d 15N/14N` <- apply_n_blank(
      Sample_df$`Area All N`, Sample_df$`d 15N/14N`,
      Mass_df2$`Area All N`, Mass_df2$`d 15N/14N`)
  }

  if (nrow(International_df) > 0) {
    International_df <- stamp_dual_outliers(
      International_df,
      resolve_excl(exclude_intl_c, exclude_intl),
      resolve_excl(exclude_intl_n, exclude_intl),
      "outlier_C", "outlier_N")
    International_df[["Row number"]] <- seq_len(nrow(International_df))
    International_df[["Plot ID"]] <- International_df[["Row number"]]
  }
  if (nrow(Mass_df) > 0) {
    Mass_df <- stamp_dual_outliers(
      Mass_df,
      resolve_excl(exclude_mass_c, exclude_mass),
      resolve_excl(exclude_mass_n, exclude_mass),
      "outlier_C", "outlier_N")
    Mass_df[["Row number"]] <- seq_len(nrow(Mass_df))
    Mass_df[["Plot ID"]] <- Mass_df[["Row number"]]
  }

  fit_int_c <- if (nrow(International_df) > 0)
    International_df[International_df$outlier_C != "Yes", , drop = FALSE]
  else International_df
  fit_int_n <- if (nrow(International_df) > 0)
    International_df[International_df$outlier_N != "Yes", , drop = FALSE]
  else International_df

  has_intl_C <- all(c("NBS18", "CAFFEINE") %in% unique(fit_int_c$`Identifier 1`))
  has_intl_N <- all(c("N2", "CAFFEINE") %in% unique(fit_int_n$`Identifier 1`))

  if (has_intl_C && nrow(fit_int_c) > 0) {
    mC <- lm(`True d 13C/12C` ~ `Blank corrected d 13C/12C`,
             data = fit_int_c, na.action = na.exclude)
    results$C_slope <- unname(coef(mC)[2])
    results$C_intercept <- unname(coef(mC)[1])
    results$C_r2 <- summary(mC)$r.squared
    results$modelC <- mC
    International_df$`International corrected d 13C/12C` <-
      International_df$`Blank corrected d 13C/12C` * results$C_slope + results$C_intercept
  } else if (nrow(International_df) > 0) {
    International_df$`International corrected d 13C/12C` <-
      International_df$`Blank corrected d 13C/12C`
  }

  if (has_intl_N && nrow(fit_int_n) > 0) {
    mN <- lm(`True d 15N/14N` ~ `Blank corrected d 15N/14N`,
             data = fit_int_n, na.action = na.exclude)
    results$N_slope <- unname(coef(mN)[2])
    results$N_intercept <- unname(coef(mN)[1])
    results$N_r2 <- summary(mN)$r.squared
    results$modelN <- mN
    International_df$`International corrected d 15N/14N` <-
      International_df$`Blank corrected d 15N/14N` * results$N_slope + results$N_intercept
  } else if (nrow(International_df) > 0) {
    International_df$`International corrected d 15N/14N` <-
      International_df$`Blank corrected d 15N/14N`
  }

  # Mass centering refs: non-BLANK sample Area means for C and N
  # (same ref for Mass_df and Sample_df). Fall back to inhouse if no samples.
  samp_nonblank <- if (nrow(Sample_df) > 0)
    Sample_df[toupper(as.character(Sample_df$`Identifier 1`)) != "BLANK", , drop = FALSE]
  else Sample_df[0, ]
  area_ref_C <- if (nrow(samp_nonblank) > 0)
    mean(samp_nonblank$`Area All C`, na.rm = TRUE) else NA_real_
  area_ref_N <- if (nrow(samp_nonblank) > 0)
    mean(samp_nonblank$`Area All N`, na.rm = TRUE) else NA_real_

  fit_mass_c <- if (nrow(Mass_df) > 0)
    Mass_df[Mass_df$outlier_C != "Yes", , drop = FALSE] else Mass_df
  fit_mass_n <- if (nrow(Mass_df) > 0)
    Mass_df[Mass_df$outlier_N != "Yes", , drop = FALSE] else Mass_df

  if (nrow(Mass_df) > 1) {
    if (!is.null(results$C_slope)) {
      Mass_df$`International corrected d 13C/12C` <-
        Mass_df$`Blank corrected d 13C/12C` * results$C_slope + results$C_intercept
    } else {
      Mass_df$`International corrected d 13C/12C` <- Mass_df$`Blank corrected d 13C/12C`
    }
    if (!is.null(results$N_slope)) {
      Mass_df$`International corrected d 15N/14N` <-
        Mass_df$`Blank corrected d 15N/14N` * results$N_slope + results$N_intercept
    } else {
      Mass_df$`International corrected d 15N/14N` <- Mass_df$`Blank corrected d 15N/14N`
    }

    fit_mass_c <- Mass_df[Mass_df$outlier_C != "Yes", , drop = FALSE]
    fit_mass_n <- Mass_df[Mass_df$outlier_N != "Yes", , drop = FALSE]
    mMC <- lm(`International corrected d 13C/12C` ~ `Area All C`, data = fit_mass_c)
    mMN <- lm(`International corrected d 15N/14N` ~ `Area All N`, data = fit_mass_n)
    results$Mass_C_slope <- unname(coef(mMC)[2])
    results$Mass_C_intercept <- unname(coef(mMC)[1])
    results$Mass_C_r2 <- summary(mMC)$r.squared
    results$Mass_N_slope <- unname(coef(mMN)[2])
    results$Mass_N_intercept <- unname(coef(mMN)[1])
    results$Mass_N_r2 <- summary(mMN)$r.squared
    results$modelMassC <- mMC
    results$modelMassN <- mMN

    if (!is.finite(area_ref_C))
      area_ref_C <- mean(fit_mass_c$`Area All C`, na.rm = TRUE)
    if (!is.finite(area_ref_N))
      area_ref_N <- mean(fit_mass_n$`Area All N`[
        toupper(as.character(fit_mass_n$`Identifier 1`)) != "BLANK"], na.rm = TRUE)
    if (!is.finite(area_ref_N))
      area_ref_N <- mean(fit_mass_n$`Area All N`, na.rm = TRUE)
    results$area_ref_C <- area_ref_C
    results$area_ref_N <- area_ref_N

    Mass_df$`Mass corrected d 13C/12C` <-
      Mass_df$`International corrected d 13C/12C` -
      (Mass_df$`Area All C` - area_ref_C) * results$Mass_C_slope
    Mass_df$`Mass corrected d 15N/14N` <-
      Mass_df$`International corrected d 15N/14N` -
      (Mass_df$`Area All N` - area_ref_N) * results$Mass_N_slope

    fit_mass_c <- Mass_df[Mass_df$outlier_C != "Yes", , drop = FALSE]
    fit_mass_n <- Mass_df[Mass_df$outlier_N != "Yes", , drop = FALSE]
    mDC <- lm(`Mass corrected d 13C/12C` ~ Row, data = fit_mass_c)
    mDN <- lm(`Mass corrected d 15N/14N` ~ Row, data = fit_mass_n)
    results$Drift_C_slope <- unname(coef(mDC)[2])
    results$Drift_C_intercept <- unname(coef(mDC)[1])
    results$Drift_C_r2 <- summary(mDC)$r.squared
    results$Drift_N_slope <- unname(coef(mDN)[2])
    results$Drift_N_intercept <- unname(coef(mDN)[1])
    results$Drift_N_r2 <- summary(mDN)$r.squared
    results$modelDriftC <- mDC
    results$modelDriftN <- mDN

    Mass_df$`Drift corrected d 13C/12C` <-
      Mass_df$`Mass corrected d 13C/12C` -
      (Mass_df$Row * results$Drift_C_slope + results$Drift_C_intercept - GelAC)
    Mass_df$`Drift corrected d 15N/14N` <-
      Mass_df$`Mass corrected d 15N/14N` -
      (Mass_df$Row * results$Drift_N_slope + results$Drift_N_intercept - GelAN)
  }

  # Samples
  if (nrow(Sample_df) > 0) {
    if (!is.null(results$C_slope)) {
      Sample_df$`International corrected d 13C/12C` <-
        Sample_df$`Blank corrected d 13C/12C` * results$C_slope + results$C_intercept
    } else {
      Sample_df$`International corrected d 13C/12C` <- Sample_df$`Blank corrected d 13C/12C`
    }
    if (!is.null(results$N_slope)) {
      Sample_df$`International corrected d 15N/14N` <-
        Sample_df$`Blank corrected d 15N/14N` * results$N_slope + results$N_intercept
    } else {
      Sample_df$`International corrected d 15N/14N` <- Sample_df$`Blank corrected d 15N/14N`
    }

    if (!is.null(results$Mass_C_slope)) {
      if (!is.finite(area_ref_C))
        area_ref_C <- mean(Sample_df$`Area All C`[
          toupper(as.character(Sample_df$`Identifier 1`)) != "BLANK"], na.rm = TRUE)
      if (!is.finite(area_ref_N))
        area_ref_N <- mean(Sample_df$`Area All N`[
          toupper(as.character(Sample_df$`Identifier 1`)) != "BLANK"], na.rm = TRUE)
      Sample_df$`Mass corrected d 13C/12C` <-
        Sample_df$`International corrected d 13C/12C` -
        (Sample_df$`Area All C` - area_ref_C) * results$Mass_C_slope
      Sample_df$`Mass corrected d 15N/14N` <-
        Sample_df$`International corrected d 15N/14N` -
        (Sample_df$`Area All N` - area_ref_N) * results$Mass_N_slope
      Sample_df$`Drift corrected d 13C/12C` <-
        Sample_df$`Mass corrected d 13C/12C` -
        (Sample_df$Row * results$Drift_C_slope + results$Drift_C_intercept - GelAC)
      Sample_df$`Drift corrected d 15N/14N` <-
        Sample_df$`Mass corrected d 15N/14N` -
        (Sample_df$Row * results$Drift_N_slope + results$Drift_N_intercept - GelAN)
    } else {
      Sample_df$`Mass corrected d 13C/12C` <- Sample_df$`International corrected d 13C/12C`
      Sample_df$`Mass corrected d 15N/14N` <- Sample_df$`International corrected d 15N/14N`
      Sample_df$`Drift corrected d 13C/12C` <- Sample_df$`Mass corrected d 13C/12C`
      Sample_df$`Drift corrected d 15N/14N` <- Sample_df$`Mass corrected d 15N/14N`
    }
  }

  # ---- TCD elemental (Rmd Saving datafile) ----
  tcd_ok <- !is.null(df_TCD) && nrow(df_TCD) > 0 &&
    "Rt Flash TCD" %in% names(df_TCD) && "rArea Flash TCD" %in% names(df_TCD)

  if (tcd_ok) {
    tcd <- df_TCD[!df_TCD$`Identifier 1` %in% c("NBS18", "NBS 18", "CAFFEINE", "N2"), ]
    tcd$`Identifier 1` <- gsub(" ", "", toupper(as.character(tcd$`Identifier 1`)))
    tcd <- subset(tcd, is.na(`Rt Flash TCD`) | `Rt Flash TCD` <= 1 | `Rt Flash TCD` > 99)
    tcd <- tcd %>% group_by(Row) %>% filter(n() == 3) %>% ungroup()

    dfN <- subset(tcd, `Rt Flash TCD` >= 100 & `Rt Flash TCD` <= 180)
    dfC <- subset(tcd, `Rt Flash TCD` >= 200 & `Rt Flash TCD` <= 270)
    if (nrow(dfN) > 0 && nrow(dfC) > 0 && nrow(dfN) == nrow(dfC)) {
      dfN <- dfN %>% rename_with(~ paste0(., " N"))
      keep_n <- intersect(c("Row N", "Analysis N", "Identifier 1 N", "Identifier 2 N",
                            "Rt Flash TCD N", "rArea Flash TCD N", "Amt% Flash TCD N"),
                          names(dfN))
      # Prefer Rmd column picks by position when available
      if (ncol(dfN) >= 9) {
        dfN <- dfN[, c(1:4, 6, 8, 9), drop = FALSE]
        colnames(dfN)[1:4] <- c("Row", "Analysis", "Identifier 1", "Identifier 2")
      }
      if (ncol(dfC) >= 9) {
        dfC <- dfC %>% rename_with(~ paste0(., " C"))
        dfC <- dfC[, c(6, 8, 9), drop = FALSE]
      }
      df_total_TCD <- cbind(dfN, dfC)
      if ("Identifier 2" %in% names(df_total_TCD)) {
        df_total_TCD$`Identifier 2` <- as.numeric(gsub(",", ".", df_total_TCD$`Identifier 2`))
      }

      Blank_ID_TCD <- Mass_df1
      if (nrow(Blank_ID_TCD) > 0) {
        Blank_df_TCD <- df_total_TCD[df_total_TCD$Row %in% Blank_ID_TCD$Row, , drop = FALSE]
      } else {
        Blank_df_TCD <- df_total_TCD[0, ]
      }
      blank_area_C <- if (nrow(Blank_df_TCD) > 0 && ncol(Blank_df_TCD) >= 9)
        mean(Blank_df_TCD[[9]], na.rm = TRUE) else 0
      if (!is.finite(blank_area_C)) blank_area_C <- 0

      Mass_df_TCD <- df_total_TCD[df_total_TCD$`Identifier 1` %in% c("GELA", "GEL A"), , drop = FALSE]
      mass_out_rows <- if (nrow(Mass_df) > 0 && any(Mass_df$outlier == "Yes"))
        Mass_df$Row[Mass_df$outlier == "Yes"] else integer(0)
      Mass_df_TCD_removed <- Mass_df_TCD[Mass_df_TCD$Row %in% mass_out_rows, , drop = FALSE]
      Mass_df_TCD <- Mass_df_TCD[!Mass_df_TCD$Row %in% mass_out_rows, , drop = FALSE]

      if (nrow(Mass_df_TCD) > 0) {
        Mass_df_TCD$`µg N/cup` <- Mass_df_TCD$`Identifier 2` * 0.1664 * 1000
        Mass_df_TCD$`µg C/cup` <- Mass_df_TCD$`Identifier 2` * 0.4527 * 1000
      }
      if (nrow(Blank_df_TCD) > 0) {
        Blank_df_TCD$`µg N/cup` <- 0
        Blank_df_TCD$`µg C/cup` <- 0
      }
      if (nrow(Mass_df_TCD_removed) > 0) {
        Mass_df_TCD_removed$`µg N/cup` <- Mass_df_TCD_removed$`Identifier 2` * 0.1664 * 1000
        Mass_df_TCD_removed$`µg C/cup` <- Mass_df_TCD_removed$`Identifier 2` * 0.4527 * 1000
      }

      Mass_df_full_TCD <- rbind(Blank_df_TCD, Mass_df_TCD)
      if (nrow(Mass_df_full_TCD) > 0 &&
          "rArea Flash TCD N" %in% names(Mass_df_full_TCD) &&
          "rArea Flash TCD C" %in% names(Mass_df_full_TCD)) {
        Mass_df_modelN_TCD <- lm(`rArea Flash TCD N` ~ 0 + `µg N/cup`,
                                 data = Mass_df_full_TCD, na.action = na.exclude)
        Mass_df_modelC_TCD <- lm(`rArea Flash TCD C` ~ 0 + `µg C/cup`,
                                 data = Mass_df_full_TCD, na.action = na.exclude)
        results$modelTCD_N <- Mass_df_modelN_TCD
        results$modelTCD_C <- Mass_df_modelC_TCD
        results$TCD_N_slope <- unname(coef(Mass_df_modelN_TCD)[1])
        results$TCD_C_slope <- unname(coef(Mass_df_modelC_TCD)[1])
        results$TCD_N_r2 <- summary(Mass_df_modelN_TCD)$r.squared
        results$TCD_C_r2 <- summary(Mass_df_modelC_TCD)$r.squared

        Mass_df_full_TCD$`mg N/kg dry sample` <-
          Mass_df_full_TCD$`µg N/cup` / Mass_df_full_TCD$`Identifier 2` * 1000
        Mass_df_full_TCD$`mg C/kg dry sample` <-
          Mass_df_full_TCD$`µg C/cup` / Mass_df_full_TCD$`Identifier 2` * 1000
        Mass_df_full_TCD$`C/N` <-
          (Mass_df_full_TCD$`mg C/kg dry sample` / 12) /
          (Mass_df_full_TCD$`mg N/kg dry sample` / 14)

        tcd_merge_cols <- intersect(
          c("Row", "Rt Flash TCD N", "rArea Flash TCD N", "Amt% Flash TCD N",
            "Rt Flash TCD C", "rArea Flash TCD C", "Amt% Flash TCD C",
            "µg N/cup", "µg C/cup", "mg N/kg dry sample", "mg C/kg dry sample", "C/N"),
          names(Mass_df_full_TCD)
        )
        Mass_df$.ord <- seq_len(nrow(Mass_df))
        Mass_df <- merge(Mass_df, Mass_df_full_TCD[, tcd_merge_cols, drop = FALSE],
                         by = "Row", all.x = TRUE, sort = FALSE)
        Mass_df <- Mass_df[order(Mass_df$.ord), , drop = FALSE]
        Mass_df$.ord <- NULL

        Sample_df_TCD <- df_total_TCD[
          !(df_total_TCD$`Identifier 1` %in% c("NBS18", "CAFFEINE", "N2", "GELA", "GEL A")), ,
          drop = FALSE]
        if (nrow(Sample_df_TCD) > 0) {
          Sample_df_TCD$`µg N/cup` <-
            Sample_df_TCD$`rArea Flash TCD N` / results$TCD_N_slope
          Sample_df_TCD$`mg N/kg dry sample` <-
            Sample_df_TCD$`µg N/cup` / Sample_df_TCD$`Identifier 2` * 1000
          Sample_df_TCD$`µg C/cup` <-
            (Sample_df_TCD$`rArea Flash TCD C` - blank_area_C) / results$TCD_C_slope
          Sample_df_TCD$`mg C/kg dry sample` <-
            Sample_df_TCD$`µg C/cup` / Sample_df_TCD$`Identifier 2` * 1000
          Sample_df_TCD$`C/N` <-
            (Sample_df_TCD$`mg C/kg dry sample` / 12) /
            (Sample_df_TCD$`mg N/kg dry sample` / 14)
          stcd_cols <- intersect(
            c("Row", "Rt Flash TCD N", "rArea Flash TCD N", "Amt% Flash TCD N",
              "Rt Flash TCD C", "rArea Flash TCD C", "Amt% Flash TCD C",
              "µg N/cup", "µg C/cup", "mg N/kg dry sample", "mg C/kg dry sample", "C/N"),
            names(Sample_df_TCD)
          )
          Sample_df$.ord <- seq_len(nrow(Sample_df))
          Sample_df <- merge(Sample_df, Sample_df_TCD[, stcd_cols, drop = FALSE],
                             by = "Row", all.x = TRUE, sort = FALSE)
          Sample_df <- Sample_df[order(Sample_df$.ord), , drop = FALSE]
          Sample_df$.ord <- NULL
        }
        results$has_tcd <- TRUE
      }
    }
  }
  if (is.null(results$has_tcd)) results$has_tcd <- FALSE

  # Possibly bad sample flags (Rmd)
  if (nrow(Sample_df) > 0) {
    if (!"Comment" %in% names(Sample_df)) Sample_df$Comment <- NA_character_
    Sample_df <- Sample_df %>%
      mutate(
        Comment = ifelse(
          (`d 15N/14N` == -1.6 | `Area All N` < 4) &
            !(toupper(as.character(`Identifier 1`)) %in% c("BLANK")),
          "Nitrogen area low / no Peak for nitrogen - double check results and compare to inhouse standards",
          Comment
        ),
        across(any_of(c("Sample Dilution N", "Area All N", "d 15N/14N",
                        "Blank corrected d 15N/14N",
                        "International corrected d 15N/14N",
                        "Mass corrected d 15N/14N",
                        "Drift corrected d 15N/14N")),
               ~ ifelse(`d 15N/14N` == -1.6, NA, .)),
        Comment = ifelse(
          !(toupper(as.character(`Identifier 1`)) %in% c("BLANK")) &
            (`Area All C` < 3 | `d 13C/12C` < -26),
          ifelse(is.na(Comment) | Comment == "",
                 "Carbon area low / isotopic ratio very negative",
                 paste(Comment, "Carbon area low / isotopic ratio very negative", sep = "; ")),
          Comment
        ),
        `Possibly bad sample` = ifelse(
          !(toupper(as.character(`Identifier 1`)) %in% c("BLANK")) & (
            `d 15N/14N` == -1.6 |
              `Area All N` < 4 |
              `Area All C` < 3 |
              `d 13C/12C` < -26
          ),
          1L, 0L
        )
      )
    # Rmd: blank sample rows get corrected / elemental cols blanked
    is_blank_s <- toupper(as.character(Sample_df$`Identifier 1`)) == "BLANK"
    if (any(is_blank_s)) {
      blank_cols <- grep(
        "corrected d |µg |mg |C/N|rArea Flash|Amt% Flash|Rt Flash|Blank corrected",
        names(Sample_df), value = TRUE)
      Sample_df[is_blank_s, blank_cols] <- NA
    }
    Sample_df <- arrange(Sample_df, Row)
  }

  # Round corrected isotope cols after fits; coefficients stay full precision
  International_df <- round_thermo_corrected(International_df)
  Mass_df <- round_thermo_corrected(Mass_df)
  Sample_df <- round_thermo_corrected(Sample_df)

  # Re-attach blank rows to mass for export (Rmd)
  if (nrow(Mass_df1) > 0 && nrow(Mass_df) > 0) {
    miss <- setdiff(names(Mass_df), names(Mass_df1))
    for (col in miss) Mass_df1[[col]] <- NA
    Mass_df1 <- Mass_df1[, names(Mass_df), drop = FALSE]
    if (nrow(Mass_df1) >= 1) {
      Mass_df <- rbind(Mass_df1[1, , drop = FALSE], Mass_df)
      if (nrow(Mass_df1) >= 2)
        Mass_df <- rbind(Mass_df, Mass_df1[2, , drop = FALSE])
    }
  }

  results$International_df <- International_df
  results$Mass_df <- Mass_df
  results$Sample_df <- Sample_df
  results$has_intl_C <- has_intl_C
  results$has_intl_N <- has_intl_N
  results
}

