        "Mass check - Nitrogen", "Area All N", "Mass corr d15N")
    })
    output$q_drift_check_c <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      mdf <- mdf[toupper(as.character(mdf$`Identifier 1`)) != "BLANK", , drop = FALSE]
      keep <- mdf[mdf$outlier_C != "Yes", , drop = FALSE]
      validate(need(nrow(keep) > 1 && "Drift corrected d 13C/12C" %in% names(keep),
                    "Not enough inhouse left after removals."))
      plot_std_scatter(keep, "Row", "Drift corrected d 13C/12C",
        "Drift check - Carbon", "Row", "Drift corr d13C")
    })
    output$q_drift_check_n <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      mdf <- mdf[toupper(as.character(mdf$`Identifier 1`)) != "BLANK", , drop = FALSE]
      keep <- mdf[mdf$outlier_N != "Yes", , drop = FALSE]
      validate(need(nrow(keep) > 1 && "Drift corrected d 15N/14N" %in% names(keep),
                    "Not enough inhouse left after removals."))
      plot_std_scatter(keep, "Row", "Drift corrected d 15N/14N",
        "Drift check - Nitrogen", "Row", "Drift corr d15N")
    })

    output$tcd_plots_ui <- renderUI({
      res <- preview()
      if (!isTRUE(res$has_tcd)) return(NULL)
      tagList(
        h4("TCD elemental (if present)"),
        fluidRow(
          column(6, plotOutput(ns("q_tcd_c"), height = "380px")),
          column(6, plotOutput(ns("q_tcd_n"), height = "380px")))
      )
    })
    output$q_tcd_c <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      mdf <- mdf[toupper(as.character(mdf$`Identifier 1`)) != "BLANK", , drop = FALSE]
      validate(need(isTRUE(res$has_tcd) && "µg C/cup" %in% names(mdf), "No TCD C data."))
      plot_std_scatter(mdf, "rArea Flash TCD C", "µg C/cup",
        "TCD - Carbon", "rArea Flash TCD C", "µg C/cup",
        exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_c), through_origin = TRUE)
    })
    output$q_tcd_n <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      mdf <- mdf[toupper(as.character(mdf$`Identifier 1`)) != "BLANK", , drop = FALSE]
      validate(need(isTRUE(res$has_tcd) && "µg N/cup" %in% names(mdf), "No TCD N data."))
      plot_std_scatter(mdf, "rArea Flash TCD N", "µg N/cup",
        "TCD - Nitrogen", "rArea Flash TCD N", "µg N/cup",
        exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_n), through_origin = TRUE)
    })

    # ---- Samples / coefficients ----
    output$sample_table <- renderDT({
      res <- corrected()
      sdf <- res$Sample_df
      validate(need(!is.null(sdf) && nrow(sdf) > 0, msg_notran))
      sdf <- pick_cols(sdf, export_sample_cols_ea)
      style_corr_dt(sdf, c("Drift corrected d 15N/14N", "Drift corrected d 13C/12C", "C/N"),
                    red_col = "Possibly bad sample")
