    output$coef_table <- renderTable({
      res <- corrected()
      validate(need(!is.null(res$C_slope) || !is.null(res$N_slope) ||
                      !is.null(res$Mass_C_slope),
                    "Press 'Apply corrections' first."))
      build_thermo_coef_df(res)
    }, digits = 10)

    output$flags <- renderText({
      ld <- loaded()
      msgs <- character(0)
      if (length(ld$flags$manipulated_rows) > 0)
        msgs <- c(msgs, paste0("Manipulated peak rows: ",
                               paste(ld$flags$manipulated_rows, collapse = ", ")))
      msgs <- c(msgs, paste0("Intl standards: ", ld$flags$n_intl,
                             " | Inhouse: ", ld$flags$n_mass,
                             " | Samples: ", ld$flags$n_samp))
      if (length(msgs) == 0) "Ready." else paste(msgs, collapse = "\n")
    })

    output$download_wb <- downloadHandler(
      filename = function() {
        base <- if (!is.null(input$file))
          tools::file_path_sans_ext(input$file$name) else "Corrected"
        paste0(base, "_corrected.xlsx")
      },
      contentType = xlsx_content_type,
      content = function(file) {
        res <- corrected()
        wb <- build_thermo_workbook(res)
        on.exit(clear_embed_tmp(), add = TRUE)
        saveWorkbook(wb, file, overwrite = TRUE)
      }
    )

    output$download_csv <- downloadHandler(
      filename = function() {
        base <- if (!is.null(input$file))
          tools::file_path_sans_ext(input$file$name) else "Corrected"
        paste0(base, "_corrected_csv.zip")
      },
      contentType = csv_zip_content_type,
      content = function(file) {
        res <- corrected()
        exp <- format_thermo_export(res)
        sheets <- list(
          Samples = exp$Sample_df,
          International_standards = exp$International_df,
          Inhouse_standards = exp$Mass_df,
          Coefficients = build_thermo_coef_df(res)
        )
        write_sheets_csv_zip(sheets, file)
      }
    )
  })
}

