sercon_clear_embed_tmp <- function() {
  if (length(.sercon_embed_env$files)) unlink(.sercon_embed_env$files)
  .sercon_embed_env$files <- character(0)
}

round_corrected_like_raw_cn <- function(df) {
  if (is.null(df) || !nrow(df)) return(df)
  dn <- decimal_places(df[["d 15N/14N"]], 3L)
  dc <- decimal_places(df[["d 13C/12C"]], 3L)
  n_cols <- grep("corrected d 15N|Blank corrected-TrueN|Measured-TrueN",
                 names(df), value = TRUE)
  c_cols <- grep("corrected d 13C|Blank corrected-TrueC|Measured-TrueC",
                 names(df), value = TRUE)
  for (nm in n_cols) df[[nm]] <- round(as.numeric(df[[nm]]), dn)
  for (nm in c_cols) df[[nm]] <- round(as.numeric(df[[nm]]), dc)
  df
}

blank_mass_balance <- function(area, delta, blank_area, blank_delta) {
  ba <- ifelse(is.na(blank_area), 0, blank_area)
  bd <- ifelse(is.na(blank_delta), 0, blank_delta)
  (area * delta - ba * bd) / (area - ba)
}

safe_mean <- function(x) {
  m <- mean(as.numeric(x), na.rm = TRUE)
  if (!is.finite(m)) NA_real_ else m
}

