#' Load a Sercon Callisto raw .xls (skip=6, cut before Drift Corrected)
load_sercon_raw <- function(path) {
  df <- as.data.frame(read_xls(path, skip = 6), stringsAsFactors = FALSE)
  drift_idx <- which(df[[1]] == "Drift Corrected")
  if (length(drift_idx) > 0) {
    cut_at <- drift_idx[1] - 2
    if (cut_at >= 1) df <- df[seq_len(cut_at), , drop = FALSE]
  }

  col2 <- names(df)[2]
  df <- df %>%
    mutate(
      well_token = str_extract(.data[[col2]], "\\b[A-H](?:[1-9]|1[0-2])\\b"),
      !!col2 := if_else(!is.na(well_token), well_token, .data[[col2]])
    ) %>%
    select(-well_token)

  df <- df %>%
    mutate(
      well_raw   = .data[[col2]],
      is_well    = str_detect(well_raw, "^[A-H]\\d{1,2}$"),
      row_letter = if_else(is_well, str_extract(well_raw, "^[A-H]"), NA_character_),
      col_number = if_else(is_well, str_extract(well_raw, "\\d+$"), NA_character_)
    ) %>%
    mutate(last_row_letter = row_letter) %>%
    tidyr::fill(last_row_letter, .direction = "down") %>%
    mutate(
      prev_row_letter = lag(last_row_letter),
      restart_A1 = (well_raw == "A1") & !is.na(prev_row_letter) & (prev_row_letter != "A"),
      dup_mode = cumsum(replace_na(restart_A1, FALSE)) > 0,
      well_new = if_else(
        is_well,
        str_c(str_dup(row_letter, if_else(dup_mode, 2L, 1L)), col_number),
        well_raw
      ),
      !!col2 := well_new
    ) %>%
    select(-well_raw, -is_well, -row_letter, -col_number, -last_row_letter,
           -prev_row_letter, -restart_A1, -dup_mode, -well_new)

  df <- df[, seq_len(min(18L, ncol(df))), drop = FALSE]
  for (j in intersect(c(1L, 3:17), seq_len(ncol(df)))) {
    df[[j]] <- as.numeric(gsub(",", ".", as.character(df[[j]])))
  }
  names(df) <- make.names(names(df), unique = TRUE)
  keep_idx <- c(1:5, 7, 9:12, 14:17)
  keep_idx <- keep_idx[keep_idx <= ncol(df)]
  df <- df[, keep_idx, drop = FALSE]
  colnames(df) <- c(
    "Row", "Identifier 1", "Identifier 2", "Area All N", "N (sam)",
    "d 15N/14N", "Ratio 1", "Ratio 2", "Area All C", "C (sam)",
    "d 13C/12C", "d 18O/16O", "Ratio 2.1", "Ratio 2.2"
  )[seq_len(ncol(df))]

  df[["Identifier 1"]] <- gsub(" ", "", toupper(as.character(df[["Identifier 1"]])))
  # Drop system blanks and N(sam)==0 (Rmd)
  n_sam <- gsub(",", ".", as.character(df[["N (sam)"]]))
  df <- df[!is.na(n_sam) & n_sam != "0", , drop = FALSE]
  df <- df[!df[["Identifier 1"]] %in% c("SYSTEMBLANK", "SYSTEMBLANK "), , drop = FALSE]
  df <- df[!grepl("^SYSTEMBLANK$", gsub(" ", "", df[["Identifier 1"]])), , drop = FALSE]
  rownames(df) <- NULL
  df
}

#' Load a weighing template xlsx (Box pos header). Returns list(df, conf, sheet_name)
load_sercon_template <- function(path) {
  if (is.null(path) || !nzchar(path) || !file.exists(path)) return(NULL)
  raw <- openxlsx::read.xlsx(path, colNames = FALSE)
  if (is.null(raw) || nrow(raw) < 2) return(NULL)
  names(raw) <- paste0("X", seq_len(ncol(raw)))
  sheet_name <- tryCatch(as.character(raw[1, 2]), error = function(e) NA_character_)
  if (is.na(sheet_name) || !nzchar(sheet_name)) {
    sheet_name <- tools::file_path_sans_ext(basename(path))
  }
  # Fix Excel serial date in row 2 if present
  try({
    if (ncol(raw) >= 2 && !is.na(raw[2, 2]) && is.numeric(raw[2, 2])) {
      raw[2, 2] <- as.character(as.Date(as.numeric(raw[2, 2]), origin = "1899-12-30"))
    }
  }, silent = TRUE)

  box_row <- which(raw$X1 == "Box pos")
  if (!length(box_row)) return(NULL)
  start_row <- box_row[1] + 1
  tmpl_df <- raw[start_row:nrow(raw), , drop = FALSE]
  tmpl_df <- tmpl_df[!is.na(tmpl_df$X3), , drop = FALSE]
  rownames(tmpl_df) <- NULL
  if (nrow(tmpl_df) == 0) return(NULL)
  tmpl_df$X3 <- as.numeric(tmpl_df$X3)
  tmpl_df$X4 <- as.numeric(tmpl_df$X4)
  colnames(tmpl_df)[1:min(4, ncol(tmpl_df))] <-
    c("Identifier 1", "Sample name", "Measured weight", "Target weight")[1:min(4, ncol(tmpl_df))]
  tmpl_df[["Identifier 1"]] <- gsub(" ", "", toupper(as.character(tmpl_df[["Identifier 1"]])))

  # Full template sheet for export (Rmd merge of header + body)
  conf <- raw[box_row[1]:nrow(raw), , drop = FALSE]
  conf$X5 <- seq_len(nrow(conf))
  hdr <- tryCatch(raw[seq_len(box_row[1] - 1), , drop = FALSE], error = function(e) NULL)
  if (!is.null(hdr) && nrow(hdr) > 0) {
    hdr$X5 <- 2:(nrow(hdr) + 1)
    merged <- merge(conf, hdr, by = "X5", all.x = TRUE)
    merged <- merged[2:nrow(merged), 2:ncol(merged), drop = FALSE]
  } else {
    merged <- conf[2:nrow(conf), seq_len(ncol(conf) - 1), drop = FALSE]
  }
  colnames(merged)[1:min(4, ncol(merged))] <-
    c("Identifier 1", "Sample name", "Measured weight", "Target weight")[1:min(4, ncol(merged))]
  if ("Measured weight" %in% names(merged))
    merged[["Measured weight"]] <- as.numeric(merged[["Measured weight"]])
  if ("Target weight" %in% names(merged))
    merged[["Target weight"]] <- as.numeric(merged[["Target weight"]])

  list(df = tmpl_df[, 1:min(4, ncol(tmpl_df)), drop = FALSE],
       conf = merged, sheet_name = sheet_name)
}

#' Merge weighing templates into raw Sercon table (Sample name -> Identifier 1, well -> Runname)
merge_sercon_templates <- function(df, template1 = NULL, template2 = NULL) {
  df <- as.data.frame(df, stringsAsFactors = FALSE)
  if ("Identifier 2" %in% names(df)) {
    df[["Identifier 2"]][df[["Identifier 2"]] == 100] <- NA
  }
  std_names <- c("GEL A", "GELA", "BLANK", "GELA", "GEL A", "CAFFEINE", "NBS18", "N2")

  if (!is.null(template1) && !is.null(template1$df)) {
    t1 <- template1$df[, intersect(c("Identifier 1", "Sample name", "Measured weight"),
                                   names(template1$df)), drop = FALSE]
    df <- merge(df, t1, by = "Identifier 1", all.x = TRUE)
    df <- df %>%
      mutate(
        `Sample name` = ifelse(`Identifier 1` %in% std_names, `Identifier 1`, `Sample name`),
        `Identifier 2` = ifelse(is.na(`Identifier 2`), `Measured weight`, `Identifier 2`)
      ) %>%
      select(-any_of("Measured weight"))
  }

  if (!is.null(template2) && !is.null(template2$df)) {
    t2 <- template2$df[, intersect(c("Identifier 1", "Sample name", "Measured weight"),
                                   names(template2$df)), drop = FALSE]
    # Rmd: second box wells are doubled (A1→AA1, B2→BB2) to match raw after
    # the second tray restart (load_sercon_raw dup_mode).
    id2 <- as.character(t2[["Identifier 1"]])
    is_well <- grepl("^[A-H][0-9]{1,2}$", id2)
    t2[["Identifier 1"]][is_well] <- paste0(substr(id2[is_well], 1, 1), id2[is_well])

    df <- merge(df, t2, by = "Identifier 1", all.x = TRUE, suffixes = c(".x", ".y"))
    if ("Sample name.x" %in% names(df) || "Sample name.y" %in% names(df)) {
      if (!"Sample name.x" %in% names(df)) df[["Sample name.x"]] <- NA_character_
      if (!"Sample name.y" %in% names(df)) df[["Sample name.y"]] <- NA_character_
      df <- df %>%
        mutate(
          `Sample name` = ifelse(is.na(`Sample name.x`), `Sample name.y`, `Sample name.x`),
          `Identifier 2` = ifelse(is.na(`Identifier 2`), `Measured weight`, `Identifier 2`)
        ) %>%
        select(-any_of(c("Sample name.x", "Sample name.y", "Measured weight")))
    } else if ("Sample name" %in% names(df) && "Measured weight" %in% names(df)) {
      df <- df %>%
        mutate(
          `Identifier 2` = ifelse(is.na(`Identifier 2`), `Measured weight`, `Identifier 2`)
        ) %>%
        select(-any_of("Measured weight"))
    }
  }

  if ("Sample name" %in% names(df)) {
    df <- df %>%
      arrange(Row) %>%
      relocate(`Identifier 1`, .before = 3) %>%
      rename(`Runname` = `Identifier 1`, `Identifier 1` = `Sample name`)
  } else if (!"Runname" %in% names(df)) {
    df[["Runname"]] <- df[["Identifier 1"]]
  }

  df[["Identifier 1"]] <- gsub(" ", "", as.character(df[["Identifier 1"]]))
  df[["Identifier 1"]] <- toupper(df[["Identifier 1"]])
  # GEL A -> GELA after space strip already; ensure GELA form
  df[["Identifier 1"]][df[["Identifier 1"]] %in% c("GELA", "GELA")] <- "GELA"
  df
}

#' Split International / Mass / Samples and attach true values + placeholder cols
format_sercon_split <- function(df, std = sercon_std_values) {
  df <- as.data.frame(df, stringsAsFactors = FALSE)
  id1 <- df[["Identifier 1"]]

  International_df <- df[id1 %in% International_ID, , drop = FALSE]
  Mass_df <- df[id1 %in% Mass_ID, , drop = FALSE]
  Sample_df <- df[!(id1 %in% Sample_ID), , drop = FALSE]

  add_num <- function(x) {
    for (nm in setdiff(names(x), c("Identifier 1", "Runname", "Comment", "outlier", "Sample name"))) {
      if (is.character(x[[nm]]) || is.factor(x[[nm]])) {
        x[[nm]] <- as.numeric(gsub(",", ".", as.character(x[[nm]])))
      }
    }
    x
  }

  # --- International ---
  International_df[["True d 13C/12C"]] <- ifelse(International_df[["Identifier 1"]] %in% Blank_ID,
                                                NA_real_, NA_real_)
  International_df[["True d 15N/14N"]] <- NA_real_
  International_df[["Blank corrected d 13C/12C"]] <- NA_real_
  International_df[["Blank corrected d 15N/14N"]] <- NA_real_
  International_df[["International corrected d 13C/12C"]] <- NA_real_
  International_df[["International corrected d 15N/14N"]] <- NA_real_
  International_df[["Blank corrected-TrueN"]] <- NA_real_
  International_df[["Blank corrected-TrueC"]] <- NA_real_
  International_df[["Comment"]] <- NA_character_

  i1 <- International_df[["Identifier 1"]]
  International_df[["True d 13C/12C"]][i1 %in% c("NBS18", "NBS 18")] <- std$NBS18
  International_df[["True d 15N/14N"]][i1 %in% c("NBS18", "NBS 18")] <- NA_real_
  International_df[["True d 13C/12C"]][i1 %in% c("N2", "N 2")] <- NA_real_
  International_df[["True d 15N/14N"]][i1 %in% c("N2", "N 2")] <- std$N2
  International_df[["True d 13C/12C"]][i1 == "CAFFEINE"] <- std$CaffeineC
  International_df[["True d 15N/14N"]][i1 == "CAFFEINE"] <- std$CaffeineN

  # Null N cols for NBS18 / null C cols for N2 (Rmd)
  n_null <- i1 %in% NO_N
  c_null <- i1 %in% NO_C
  for (nm in c("Area All N", "N (sam)", "d 15N/14N", "Ratio 1", "Ratio 2",
               "True d 15N/14N", "Blank corrected d 15N/14N",
               "Blank corrected-TrueN", "International corrected d 15N/14N")) {
    if (nm %in% names(International_df)) International_df[[nm]][n_null] <- NA
  }
  for (nm in c("Area All C", "C (sam)", "d 13C/12C", "d 18O/16O", "Ratio 2.1", "Ratio 2.2",
               "True d 13C/12C", "Blank corrected d 13C/12C",
               "Blank corrected-TrueC", "International corrected d 13C/12C")) {
    if (nm %in% names(International_df)) International_df[[nm]][c_null] <- NA
  }

  International_df[["Blank corrected-TrueN"]] <-
    International_df[["d 15N/14N"]] - International_df[["True d 15N/14N"]]
  International_df[["Blank corrected-TrueC"]] <-
    International_df[["d 13C/12C"]] - International_df[["True d 13C/12C"]]

  # --- Mass (GEL A) ---
  Mass_df[["True d 13C/12C"]] <- ifelse(Mass_df[["Identifier 1"]] %in% Blank_ID, NA_real_, std$GelAC)
  Mass_df[["True d 15N/14N"]] <- ifelse(Mass_df[["Identifier 1"]] %in% Blank_ID, NA_real_, std$GelAN)
  for (nm in c("Blank corrected d 13C/12C", "Blank corrected d 15N/14N",
               "International corrected d 13C/12C", "International corrected d 15N/14N",
               "Mass corrected d 13C/12C", "Mass corrected d 15N/14N",
               "Drift corrected d 13C/12C", "Drift corrected d 15N/14N",
               "Blank corrected-TrueN", "Blank corrected-TrueC")) {
    Mass_df[[nm]] <- NA_real_
  }
  Mass_df[["Comment"]] <- NA_character_
  Mass_df[["Blank corrected-TrueN"]] <- Mass_df[["d 15N/14N"]] - Mass_df[["True d 15N/14N"]]
  Mass_df[["Blank corrected-TrueC"]] <- Mass_df[["d 13C/12C"]] - Mass_df[["True d 13C/12C"]]

  # --- Samples ---
  for (nm in c("Blank corrected d 13C/12C", "Blank corrected d 15N/14N",
               "International corrected d 13C/12C", "International corrected d 15N/14N",
               "Mass corrected d 13C/12C", "Mass corrected d 15N/14N",
               "Drift corrected d 13C/12C", "Drift corrected d 15N/14N")) {
    Sample_df[[nm]] <- NA_real_
  }
  Sample_df[["Comment"]] <- NA_character_

  International_df <- add_num(International_df)
  Mass_df <- add_num(Mass_df)
  Sample_df <- add_num(Sample_df)
  International_df$outlier <- "No"
  Mass_df$outlier <- "No"

  list(International_df = International_df, Mass_df = Mass_df, Sample_df = Sample_df)
}

# ==================================================================
# CORRECTION PIPELINE
# ==================================================================

apply_sercon_corrections <- function(International_df, Mass_df, Sample_df,
                                     std = sercon_std_values,
                                     exclude_intl = integer(0),
                                     exclude_mass = integer(0),
                                     exclude_intl_c = NULL, exclude_intl_n = NULL,
                                     exclude_mass_c = NULL, exclude_mass_n = NULL,
                                     blank_correct_n = FALSE) {
  results <- list()
  International_df <- as.data.frame(International_df, stringsAsFactors = FALSE)
  Mass_df <- as.data.frame(Mass_df, stringsAsFactors = FALSE)
  Sample_df <- as.data.frame(Sample_df, stringsAsFactors = FALSE)

  # Separate blanks (Rmd)
  intl_blank <- International_df[International_df[["Identifier 1"]] %in% Blank_ID, , drop = FALSE]
  mass_blank <- Mass_df[Mass_df[["Identifier 1"]] %in% Blank_ID, , drop = FALSE]
  International_df <- International_df[!(International_df[["Identifier 1"]] %in% Blank_ID), , drop = FALSE]
  Mass_df <- Mass_df[!(Mass_df[["Identifier 1"]] %in% Blank_ID), , drop = FALSE]
  rownames(International_df) <- NULL
  rownames(Mass_df) <- NULL

  International_df[["Row number"]] <- seq_len(nrow(International_df))
  Mass_df[["Row number"]] <- seq_len(nrow(Mass_df))
  International_df <- stamp_dual_outliers(
    International_df,
    resolve_excl(exclude_intl_c, exclude_intl),
    resolve_excl(exclude_intl_n, exclude_intl),
    "outlier_C", "outlier_N")
  Mass_df <- stamp_dual_outliers(
    Mass_df,
    resolve_excl(exclude_mass_c, exclude_mass),
    resolve_excl(exclude_mass_n, exclude_mass),
    "outlier_C", "outlier_N")

  # Rmd default: Mass_df1[,4:6] <- NA → N blank means 0 → N passthrough.
  # Some runs (e.g. 260318) keep blank N and blank-correct N on intl/mass/samples.
  if (!isTRUE(blank_correct_n) && nrow(mass_blank) > 0) {
    for (nm in intersect(c("Area All N", "N (sam)", "d 15N/14N"), names(mass_blank))) {
      mass_blank[[nm]] <- NA_real_
    }
  }

  # Blank means from blank cups (Sercon: N often unused / NA for mass blanks)
  blank_area_C_intl <- safe_mean(intl_blank[["Area All C"]])
  blank_d13_intl <- safe_mean(intl_blank[["d 13C/12C"]])
  blank_area_C_mass <- safe_mean(mass_blank[["Area All C"]])
  blank_d13_mass <- safe_mean(mass_blank[["d 13C/12C"]])
  blank_area_N_mass <- safe_mean(mass_blank[["Area All N"]])
  blank_d15_mass <- safe_mean(mass_blank[["d 15N/14N"]])
  # Rmd sample C blank uses Mass_df2 area + Mass_df1 delta + International_df1 denom
  blank_area_C_for_samp_denom <- blank_area_C_intl
  blank_d13_for_samp <- blank_d13_mass
  blank_area_C_for_samp <- blank_area_C_mass

  # --- Blank correction ---
  # N: Rmd default passthrough; optional blank_correct_n uses mass-blank means
  if (isTRUE(blank_correct_n) && is.finite(blank_area_N_mass) && is.finite(blank_d15_mass)) {
    International_df[["Blank corrected d 15N/14N"]] <- blank_mass_balance(
      International_df[["Area All N"]], International_df[["d 15N/14N"]],
      blank_area_N_mass, blank_d15_mass
    )
    Mass_df[["Blank corrected d 15N/14N"]] <- blank_mass_balance(
      Mass_df[["Area All N"]], Mass_df[["d 15N/14N"]],
      blank_area_N_mass, blank_d15_mass
    )
  } else {
    International_df[["Blank corrected d 15N/14N"]] <- International_df[["d 15N/14N"]]
    Mass_df[["Blank corrected d 15N/14N"]] <- Mass_df[["d 15N/14N"]]
  }
  International_df[["Blank corrected d 13C/12C"]] <- blank_mass_balance(
    International_df[["Area All C"]], International_df[["d 13C/12C"]],
    blank_area_C_intl, blank_d13_intl
  )
  # Rmd: mass C blank denom uses International blank area (quirky but faithful)
  Mass_df[["Blank corrected d 13C/12C"]] <- blank_mass_balance(
    Mass_df[["Area All C"]], Mass_df[["d 13C/12C"]],
    blank_area_C_intl, blank_d13_mass
  )

  International_df[["Blank corrected-TrueN"]] <-
    International_df[["Blank corrected d 15N/14N"]] - International_df[["True d 15N/14N"]]
  International_df[["Blank corrected-TrueC"]] <-
    International_df[["Blank corrected d 13C/12C"]] - International_df[["True d 13C/12C"]]
  Mass_df[["Blank corrected-TrueN"]] <-
    Mass_df[["Blank corrected d 15N/14N"]] - Mass_df[["True d 15N/14N"]]
  Mass_df[["Blank corrected-TrueC"]] <-
    Mass_df[["Blank corrected d 13C/12C"]] - Mass_df[["True d 13C/12C"]]

  if (nrow(Sample_df) > 0) {
    # N: Mass blank N means are NA/0 (Rmd Mass_df1[,4:6] <- NA) → passthrough
    Sample_df[["Blank corrected d 15N/14N"]] <- blank_mass_balance(
      Sample_df[["Area All N"]], Sample_df[["d 15N/14N"]],
      blank_area_N_mass, blank_d15_mass
    )
    # C: (A*d - mean(Mass Area C)*mean(Mass d13)) / (A - mean(Intl Area C))
    Sample_df[["Blank corrected d 13C/12C"]] <- (
      Sample_df[["Area All C"]] * Sample_df[["d 13C/12C"]] -
        ifelse(is.na(blank_area_C_for_samp), 0, blank_area_C_for_samp) *
        ifelse(is.na(blank_d13_for_samp), 0, blank_d13_for_samp)
    ) / (
      Sample_df[["Area All C"]] -
        ifelse(is.na(blank_area_C_for_samp_denom), 0, blank_area_C_for_samp_denom)
    )
  }

  fit_int_c <- International_df[International_df$outlier_C != "Yes", , drop = FALSE]
  fit_int_n <- International_df[International_df$outlier_N != "Yes", , drop = FALSE]
  has_C_anchors <- all(c("NBS18", "CAFFEINE") %in% fit_int_c[["Identifier 1"]])
  has_N_anchors <- all(c("N2", "CAFFEINE") %in% fit_int_n[["Identifier 1"]])

  if (has_C_anchors) {
    mC <- lm(`True d 13C/12C` ~ `Blank corrected d 13C/12C`, data = fit_int_c, na.action = na.exclude)
    results$C_slope <- unname(coef(mC)[2])
    results$C_intercept <- unname(coef(mC)[1])
    results$C_r2 <- summary(mC)$r.squared
    results$intl_model_C <- mC
    International_df[["International corrected d 13C/12C"]] <-
      International_df[["Blank corrected d 13C/12C"]] * results$C_slope + results$C_intercept
  } else {
    International_df[["International corrected d 13C/12C"]] <-
      International_df[["Blank corrected d 13C/12C"]]
  }

  if (has_N_anchors) {
    mN <- lm(`True d 15N/14N` ~ `Blank corrected d 15N/14N`, data = fit_int_n, na.action = na.exclude)
    results$N_slope <- unname(coef(mN)[2])
    results$N_intercept <- unname(coef(mN)[1])
    results$N_r2 <- summary(mN)$r.squared
    results$intl_model_N <- mN
    International_df[["International corrected d 15N/14N"]] <-
      International_df[["Blank corrected d 15N/14N"]] * results$N_slope + results$N_intercept
  } else {
    International_df[["International corrected d 15N/14N"]] <-
      International_df[["Blank corrected d 15N/14N"]]
  }

  # Apply intl to mass / samples
  if (!is.null(results$C_slope)) {
    Mass_df[["International corrected d 13C/12C"]] <-
      Mass_df[["Blank corrected d 13C/12C"]] * results$C_slope + results$C_intercept
    if (nrow(Sample_df) > 0)
      Sample_df[["International corrected d 13C/12C"]] <-
        Sample_df[["Blank corrected d 13C/12C"]] * results$C_slope + results$C_intercept
  } else {
    Mass_df[["International corrected d 13C/12C"]] <- Mass_df[["Blank corrected d 13C/12C"]]
    if (nrow(Sample_df) > 0)
      Sample_df[["International corrected d 13C/12C"]] <- Sample_df[["Blank corrected d 13C/12C"]]
  }
  if (!is.null(results$N_slope)) {
    Mass_df[["International corrected d 15N/14N"]] <-
      Mass_df[["Blank corrected d 15N/14N"]] * results$N_slope + results$N_intercept
    if (nrow(Sample_df) > 0)
      Sample_df[["International corrected d 15N/14N"]] <-
        Sample_df[["Blank corrected d 15N/14N"]] * results$N_slope + results$N_intercept
  } else {
    Mass_df[["International corrected d 15N/14N"]] <- Mass_df[["Blank corrected d 15N/14N"]]
    if (nrow(Sample_df) > 0)
      Sample_df[["International corrected d 15N/14N"]] <- Sample_df[["Blank corrected d 15N/14N"]]
  }

  # Shared sample Area mean for mass centering (non-BLANK samples)
  area_ref_C <- NA_real_
  area_ref_N <- NA_real_
  if (nrow(Sample_df) > 0) {
    id1s <- toupper(as.character(Sample_df[["Identifier 1"]]))
    keep_s <- id1s != "BLANK"
    area_ref_C <- safe_mean(Sample_df[["Area All C"]][keep_s])
    area_ref_N <- safe_mean(Sample_df[["Area All N"]][keep_s])
    if (!is.finite(area_ref_C)) area_ref_C <- safe_mean(Sample_df[["Area All C"]])
    if (!is.finite(area_ref_N)) area_ref_N <- safe_mean(Sample_df[["Area All N"]])
  }
  results$area_ref_C <- area_ref_C
  results$area_ref_N <- area_ref_N

  mass_fit_c <- Mass_df[Mass_df$outlier_C != "Yes", , drop = FALSE]
  mass_fit_n <- Mass_df[Mass_df$outlier_N != "Yes", , drop = FALSE]
  if (nrow(mass_fit_c) > 1 && nrow(mass_fit_n) > 1) {
    if (!is.finite(area_ref_C)) area_ref_C <- safe_mean(mass_fit_c[["Area All C"]])
    if (!is.finite(area_ref_N)) area_ref_N <- safe_mean(mass_fit_n[["Area All N"]])
    results$area_ref_C <- area_ref_C
    results$area_ref_N <- area_ref_N

    mMC <- lm(`International corrected d 13C/12C` ~ `Area All C`, data = mass_fit_c)
    mMN <- lm(`International corrected d 15N/14N` ~ `Area All N`, data = mass_fit_n)
    results$Mass_C_slope <- unname(coef(mMC)[2])
    results$Mass_C_intercept <- unname(coef(mMC)[1])
    results$Mass_C_r2 <- summary(mMC)$r.squared
    results$Mass_N_slope <- unname(coef(mMN)[2])
    results$Mass_N_intercept <- unname(coef(mMN)[1])
    results$Mass_N_r2 <- summary(mMN)$r.squared

    Mass_df[["Mass corrected d 13C/12C"]] <-
      Mass_df[["International corrected d 13C/12C"]] -
      (Mass_df[["Area All C"]] - area_ref_C) * results$Mass_C_slope
    Mass_df[["Mass corrected d 15N/14N"]] <-
      Mass_df[["International corrected d 15N/14N"]] -
      (Mass_df[["Area All N"]] - area_ref_N) * results$Mass_N_slope

    mass_fit_c <- Mass_df[Mass_df$outlier_C != "Yes", , drop = FALSE]
    mass_fit_n <- Mass_df[Mass_df$outlier_N != "Yes", , drop = FALSE]
    mDC <- lm(`Mass corrected d 13C/12C` ~ Row, data = mass_fit_c)
    mDN <- lm(`Mass corrected d 15N/14N` ~ Row, data = mass_fit_n)
    results$Drift_C_slope <- unname(coef(mDC)[2])
    results$Drift_C_intercept <- unname(coef(mDC)[1])
    results$Drift_C_r2 <- summary(mDC)$r.squared
    results$Drift_N_slope <- unname(coef(mDN)[2])
    results$Drift_N_intercept <- unname(coef(mDN)[1])
    results$Drift_N_r2 <- summary(mDN)$r.squared

    Mass_df[["Drift corrected d 13C/12C"]] <-
      Mass_df[["Mass corrected d 13C/12C"]] -
      (Mass_df$Row * results$Drift_C_slope + results$Drift_C_intercept - std$GelAC)
    Mass_df[["Drift corrected d 15N/14N"]] <-
      Mass_df[["Mass corrected d 15N/14N"]] -
      (Mass_df$Row * results$Drift_N_slope + results$Drift_N_intercept - std$GelAN)

    if (nrow(Sample_df) > 0) {
      Sample_df[["Mass corrected d 13C/12C"]] <-
        Sample_df[["International corrected d 13C/12C"]] -
        (Sample_df[["Area All C"]] - area_ref_C) * results$Mass_C_slope
      Sample_df[["Mass corrected d 15N/14N"]] <-
        Sample_df[["International corrected d 15N/14N"]] -
        (Sample_df[["Area All N"]] - area_ref_N) * results$Mass_N_slope
      Sample_df[["Drift corrected d 13C/12C"]] <-
        Sample_df[["Mass corrected d 13C/12C"]] -
        (Sample_df$Row * results$Drift_C_slope + results$Drift_C_intercept - std$GelAC)
      Sample_df[["Drift corrected d 15N/14N"]] <-
        Sample_df[["Mass corrected d 15N/14N"]] -
        (Sample_df$Row * results$Drift_N_slope + results$Drift_N_intercept - std$GelAN)
    }
  } else {
    Mass_df[["Mass corrected d 13C/12C"]] <- Mass_df[["International corrected d 13C/12C"]]
    Mass_df[["Mass corrected d 15N/14N"]] <- Mass_df[["International corrected d 15N/14N"]]
    Mass_df[["Drift corrected d 13C/12C"]] <- Mass_df[["Mass corrected d 13C/12C"]]
    Mass_df[["Drift corrected d 15N/14N"]] <- Mass_df[["Mass corrected d 15N/14N"]]
    if (nrow(Sample_df) > 0) {
      Sample_df[["Mass corrected d 13C/12C"]] <- Sample_df[["International corrected d 13C/12C"]]
      Sample_df[["Mass corrected d 15N/14N"]] <- Sample_df[["International corrected d 15N/14N"]]
      Sample_df[["Drift corrected d 13C/12C"]] <- Sample_df[["Mass corrected d 13C/12C"]]
      Sample_df[["Drift corrected d 15N/14N"]] <- Sample_df[["Mass corrected d 15N/14N"]]
    }
  }

  # Elemental µg from Area vs Gel stoichiometry (not Flash TCD)
  blank_area_C <- blank_area_C_mass
  gel_for_tcd <- Mass_df[Mass_df$outlier != "Yes", , drop = FALSE]
  if (nrow(gel_for_tcd) > 0) {
    gel_for_tcd[["µg N/cup"]] <- gel_for_tcd[["Identifier 2"]] * std$GelN_frac * 1000
    gel_for_tcd[["µg C/cup"]] <- gel_for_tcd[["Identifier 2"]] * std$GelC_frac * 1000
    # include blank rows with 0 µg for through-origin fit (Rmd)
    blank_tcd <- mass_blank
    if (nrow(blank_tcd) > 0) {
      blank_tcd[["µg N/cup"]] <- 0
      blank_tcd[["µg C/cup"]] <- 0
      blank_tcd[setdiff(names(gel_for_tcd), names(blank_tcd))] <- NA
      fit_tcd <- rbind(blank_tcd[, names(gel_for_tcd), drop = FALSE], gel_for_tcd)
    } else {
      fit_tcd <- gel_for_tcd
    }
    mN_tcd <- tryCatch(
      lm(`Area All N` ~ 0 + `µg N/cup`, data = fit_tcd, na.action = na.exclude),
      error = function(e) NULL)
    mC_tcd <- tryCatch(
      lm(`Area All C` ~ 0 + `µg C/cup`, data = fit_tcd, na.action = na.exclude),
      error = function(e) NULL)
    if (!is.null(mN_tcd)) {
      results$TCD_N_slope <- unname(coef(mN_tcd)[1])
      results$TCD_N_r2 <- summary(mN_tcd)$r.squared
    }
    if (!is.null(mC_tcd)) {
      results$TCD_C_slope <- unname(coef(mC_tcd)[1])
      results$TCD_C_r2 <- summary(mC_tcd)$r.squared
    }

    Mass_df[["µg N/cup"]] <- Mass_df[["Identifier 2"]] * std$GelN_frac * 1000
    Mass_df[["µg C/cup"]] <- Mass_df[["Identifier 2"]] * std$GelC_frac * 1000
    Mass_df[["mg N/kg dry sample"]] <- Mass_df[["µg N/cup"]] / Mass_df[["Identifier 2"]] * 1000
    Mass_df[["mg C/kg dry sample"]] <- Mass_df[["µg C/cup"]] / Mass_df[["Identifier 2"]] * 1000
    Mass_df[["C/N"]] <- (Mass_df[["mg C/kg dry sample"]] / 12) /
      (Mass_df[["mg N/kg dry sample"]] / 14)

    if (nrow(Sample_df) > 0 && !is.null(results$TCD_N_slope) && !is.null(results$TCD_C_slope)) {
      Sample_df[["µg N/cup"]] <- Sample_df[["Area All N"]] / results$TCD_N_slope
      Sample_df[["mg N/kg dry sample"]] <- Sample_df[["µg N/cup"]] / Sample_df[["Identifier 2"]] * 1000
      Sample_df[["µg C/cup"]] <- (Sample_df[["Area All C"]] -
        ifelse(is.na(blank_area_C), 0, blank_area_C)) / results$TCD_C_slope
      Sample_df[["mg C/kg dry sample"]] <- Sample_df[["µg C/cup"]] / Sample_df[["Identifier 2"]] * 1000
      Sample_df[["C/N"]] <- (Sample_df[["mg C/kg dry sample"]] / 12) /
        (Sample_df[["mg N/kg dry sample"]] / 14)
      # Blank sample rows: NA corrected elemental (Rmd)
      is_blank_s <- toupper(as.character(Sample_df[["Identifier 1"]])) == "BLANK"
      for (nm in c("Blank corrected d 15N/14N", "International corrected d 15N/14N",
                   "Mass corrected d 15N/14N", "Drift corrected d 15N/14N",
                   "Blank corrected d 13C/12C", "International corrected d 13C/12C",
                   "Mass corrected d 13C/12C", "Drift corrected d 13C/12C",
                   "µg N/cup", "mg N/kg dry sample", "µg C/cup", "mg C/kg dry sample", "C/N")) {
        if (nm %in% names(Sample_df)) Sample_df[[nm]][is_blank_s] <- NA
      }
    }
  }

  # If anchors missing, force intl corrected NA on export path (Rmd end of Remove outliers)
  if (!has_C_anchors) {
    International_df[["International corrected d 13C/12C"]] <- NA_real_
    Mass_df[["International corrected d 13C/12C"]] <- NA_real_
    if (nrow(Sample_df) > 0) Sample_df[["International corrected d 13C/12C"]] <- NA_real_
  }
  if (!has_N_anchors) {
    International_df[["International corrected d 15N/14N"]] <- NA_real_
    Mass_df[["International corrected d 15N/14N"]] <- NA_real_
    if (nrow(Sample_df) > 0) Sample_df[["International corrected d 15N/14N"]] <- NA_real_
  }

  # Possibly bad sample flags (Rmd commented block, enabled here).
  # Sercon Area All is ~1e-8–1e-6 (not Thermo Vs), so area cuts are relative to
  # kept GELA medians instead of the Thermo absolute thresholds (<4 / <3).
  if (nrow(Sample_df) > 0) {
    if (!"Comment" %in% names(Sample_df)) Sample_df$Comment <- NA_character_
    is_blank_s <- toupper(as.character(Sample_df[["Identifier 1"]])) %in% c("BLANK")
    gel_keep_n <- Mass_df[Mass_df$outlier_N != "Yes", , drop = FALSE]
    gel_keep_c <- Mass_df[Mass_df$outlier_C != "Yes", , drop = FALSE]
    med_n <- if (nrow(gel_keep_n) > 0) stats::median(gel_keep_n[["Area All N"]], na.rm = TRUE) else NA_real_
    med_c <- if (nrow(gel_keep_c) > 0) stats::median(gel_keep_c[["Area All C"]], na.rm = TRUE) else NA_real_
    low_n_area <- is.finite(med_n) & (Sample_df[["Area All N"]] < 0.25 * med_n)
    low_c_area <- is.finite(med_c) & (Sample_df[["Area All C"]] < 0.25 * med_c)
    no_n_peak <- is.finite(Sample_df[["d 15N/14N"]]) & (Sample_df[["d 15N/14N"]] == -1.6)
    very_neg_c <- is.finite(Sample_df[["d 13C/12C"]]) & (Sample_df[["d 13C/12C"]] < -26)
    bad_n <- !is_blank_s & (no_n_peak | low_n_area)
    bad_c <- !is_blank_s & (low_c_area | very_neg_c)

    Sample_df$Comment[bad_n] <-
      "Nitrogen area low / no Peak for nitrogen - double check results and compare to inhouse standards"
    Sample_df$Comment[bad_c] <- ifelse(
      is.na(Sample_df$Comment[bad_c]) | Sample_df$Comment[bad_c] == "",
      "Carbon area low / isotopic ratio very negative",
      paste(Sample_df$Comment[bad_c], "Carbon area low / isotopic ratio very negative", sep = "; ")
    )
    n_wipe <- c("Area All N", "d 15N/14N",
                "Blank corrected d 15N/14N",
                "International corrected d 15N/14N",
                "Mass corrected d 15N/14N",
                "Drift corrected d 15N/14N")
    for (nm in intersect(n_wipe, names(Sample_df)))
      Sample_df[[nm]][no_n_peak] <- NA
    Sample_df[["Possibly bad sample"]] <- ifelse(bad_n | bad_c, 1L, 0L)
  }

  # Round corrected / Blank-True to raw decimals (coefs stay full precision in results)
  International_df <- round_corrected_like_raw_cn(International_df)
  Mass_df <- round_corrected_like_raw_cn(Mass_df)
  Sample_df <- round_corrected_like_raw_cn(Sample_df)

  results$International_df <- International_df
  results$Mass_df <- Mass_df
  results$Sample_df <- Sample_df
  results$intl_blank <- intl_blank
  results$mass_blank <- mass_blank
  results$has_C_anchors <- has_C_anchors
  results$has_N_anchors <- has_N_anchors
  results
}

build_sercon_coef_df <- function(r) {
  data.frame(
    Correction = c("International N", "Mass N", "Drift N",
                   "International C", "Mass C", "Drift C"),
    Slope = c(r$N_slope, r$Mass_N_slope, r$Drift_N_slope,
              r$C_slope, r$Mass_C_slope, r$Drift_C_slope),
    Intercept = c(r$N_intercept, r$Mass_N_intercept, r$Drift_N_intercept,
                  r$C_intercept, r$Mass_C_intercept, r$Drift_C_intercept),
    R_squared = c(r$N_r2, r$Mass_N_r2, r$Drift_N_r2,
                  r$C_r2, r$Mass_C_r2, r$Drift_C_r2),
    stringsAsFactors = FALSE
  )
}

format_sercon_export_dfs <- function(res) {
  idf <- res$International_df
  mdf <- res$Mass_df
  sdf <- res$Sample_df
  intl_blank <- res$intl_blank
  mass_blank <- res$mass_blank

  if (!is.null(idf) && nrow(idf) > 0) {
    idf[["Plot ID"]] <- idf[["Row number"]]
    idf <- finalize_std_export(idf, sercon_intl_corrected_cols)
    # Bookend blanks (Rmd)
    if (!is.null(intl_blank) && nrow(intl_blank) > 0) {
      b <- intl_blank
      b[setdiff(names(idf), names(b))] <- NA
      b[["Plot ID"]] <- NA
      b$outlier <- if ("outlier" %in% names(b)) b$outlier else "No"
      b$outlier[is.na(b$outlier)] <- "No"
      top <- b[1, names(idf), drop = FALSE]
      bot <- b[min(2, nrow(b)), names(idf), drop = FALSE]
      idf <- rbind(top, idf, bot)
    }
    idf <- pick_cols(idf, sercon_export_intl_cols)
  }
  if (!is.null(mdf) && nrow(mdf) > 0) {
    mdf[["Plot ID"]] <- mdf[["Row number"]]
    mdf <- finalize_std_export(mdf, sercon_mass_corrected_cols)
    if (!is.null(mass_blank) && nrow(mass_blank) > 0) {
      b <- mass_blank
      b[setdiff(names(mdf), names(b))] <- NA
      b[["Plot ID"]] <- NA
      b$outlier <- if ("outlier" %in% names(b)) b$outlier else "No"
      b$outlier[is.na(b$outlier)] <- "No"
      top <- b[1, names(mdf), drop = FALSE]
      bot <- b[min(2, nrow(b)), names(mdf), drop = FALSE]
      mdf <- rbind(top, mdf, bot)
    }
    mdf <- pick_cols(mdf, sercon_export_mass_cols)
  }
  if (!is.null(sdf) && nrow(sdf) > 0) {
    sdf <- pick_cols(sdf, sercon_export_sample_cols)
  }
  list(Sample_df = sdf, International_df = idf, Mass_df = mdf)
}

build_sercon_workbook <- function(res, coef_df, template1 = NULL, template2 = NULL) {
  sercon_clear_embed_tmp()
  exp <- format_sercon_export_dfs(res)
  Sample_df <- exp$Sample_df
  International_df <- exp$International_df
  Mass_df <- exp$Mass_df

  wb <- createWorkbook()
  hs <- createStyle(fontSize = 11, fontColour = "#000000", fgFill = "grey", textDecoration = "bold")
  highlight <- createStyle(fontColour = "#000000", bgFill = "green")
  tab_cols <- c(Samples = "green", International_standards = "blue",
                Inhouse_standards = "orange", Coefficients = "grey")

  add_sheet <- function(name, dat) {
    addWorksheet(wb, name, tabColour = unname(tab_cols[[name]]))
    writeData(wb, name, dat, headerStyle = hs, withFilter = TRUE)
    if (!is.null(dat) && ncol(dat) > 0)
      setColWidths(wb, name, cols = seq_len(ncol(dat)), widths = calculate_col_widths(dat))
  }
  add_sheet("Samples", Sample_df)
  add_sheet("International_standards", International_df)
  add_sheet("Inhouse_standards", Mass_df)
  add_sheet("Coefficients", coef_df)

  cf_green <- function(sheet, dat, col_names) {
    n <- nrow(dat)
    if (is.null(dat) || n == 0) return(invisible(NULL))
    for (j in which(names(dat) %in% col_names)) {
      colref <- int_to_col_ref(j)
      conditionalFormatting(wb, sheet, cols = j, rows = 2:(n + 1),
                            rule = paste0("ISNUMBER($", colref, "2)"), style = highlight)
    }
  }
  cf_green("Samples", Sample_df, c(
    "Drift corrected d 15N/14N", "Drift corrected d 13C/12C", "C/N"))
  cf_green("International_standards", International_df, c(
    "Blank corrected-TrueN", "Blank corrected-TrueC",
    "International corrected d 15N/14N", "International corrected d 13C/12C"))
  cf_green("Inhouse_standards", Mass_df, c(
    "Blank corrected-TrueN", "Blank corrected-TrueC",
    "Drift corrected d 15N/14N", "Drift corrected d 13C/12C", "C/N"))

  cf_red <- function(sheet, dat, flag_col) {
    n <- nrow(dat)
    if (is.null(dat) || n == 0 || !flag_col %in% names(dat)) return(invisible(NULL))
    j <- which(names(dat) == flag_col)[1]
    colref <- int_to_col_ref(j)
    red_fill <- createStyle(fgFill = "#FFC7CE")
    conditionalFormatting(wb, sheet, cols = seq_len(ncol(dat)), rows = 2:(n + 1),
                          rule = paste0("$", colref, "2=1"), style = red_fill)
  }
  cf_red("Samples", Sample_df, "Possibly bad sample")

  # Template sheets
  add_tmpl <- function(tmpl) {
    if (is.null(tmpl) || is.null(tmpl$conf)) return(invisible(NULL))
    nm <- as.character(tmpl$sheet_name)
    if (!nzchar(nm)) nm <- "Template"
    # Excel sheet name max 31 chars
    nm <- substr(nm, 1, 31)
    # Avoid duplicate names
    existing <- names(wb)
    if (nm %in% existing) nm <- substr(paste0(nm, "_2"), 1, 31)
    addWorksheet(wb, nm)
    writeData(wb, nm, tmpl$conf, headerStyle = hs, withFilter = TRUE)
    setColWidths(wb, nm, cols = seq_len(ncol(tmpl$conf)),
                 widths = calculate_col_widths(tmpl$conf))
  }
  add_tmpl(template1)
  add_tmpl(template2)

  # ---- embed plots ----
  idf <- res$International_df
  mdf <- res$Mass_df
  if (!is.null(idf) && nrow(idf) > 0) {
    idf[["Plot ID"]] <- idf[["Row number"]]
    if (isTRUE(res$has_C_anchors) && !is.null(res$C_slope)) {
      sercon_embed_ggplot(wb, "International_standards",
        plot_wb_scatter(idf, "Blank corrected d 13C/12C", "True d 13C/12C",
          "International correction - Carbon",
          expression(Blank~corrected~delta^{13}*C),
          expression(True~delta^{13}*C),
          res$C_slope, res$C_intercept, res$C_r2, excl_flag = "outlier_C"),
        startRow = 20, startCol = 15)
      keep_i <- idf[idf$outlier_C != "Yes", , drop = FALSE]
      if (nrow(keep_i) > 1) {
        mC2 <- lm(keep_i[["True d 13C/12C"]] ~ keep_i[["International corrected d 13C/12C"]])
        sercon_embed_ggplot(wb, "International_standards",
          plot_wb_scatter(keep_i, "International corrected d 13C/12C", "True d 13C/12C",
            "International check - Carbon",
            expression(International~corrected~delta^{13}*C),
            expression(True~delta^{13}*C),
            unname(coef(mC2)[2]), unname(coef(mC2)[1]), summary(mC2)$r.squared,
            include_outliers = FALSE),
          startRow = 41, startCol = 15)
      }
    }
    if (isTRUE(res$has_N_anchors) && !is.null(res$N_slope)) {
      sercon_embed_ggplot(wb, "International_standards",
        plot_wb_scatter(idf, "Blank corrected d 15N/14N", "True d 15N/14N",
          "International correction - Nitrogen",
          expression(Blank~corrected~delta^{15}*N),
          expression(True~delta^{15}*N),
          res$N_slope, res$N_intercept, res$N_r2, excl_flag = "outlier_N"),
        startRow = 20, startCol = 9)
      keep_i <- idf[idf$outlier_N != "Yes", , drop = FALSE]
      if (nrow(keep_i) > 1) {
        mN2 <- lm(keep_i[["True d 15N/14N"]] ~ keep_i[["International corrected d 15N/14N"]])
        sercon_embed_ggplot(wb, "International_standards",
          plot_wb_scatter(keep_i, "International corrected d 15N/14N", "True d 15N/14N",
            "International check - Nitrogen",
            expression(International~corrected~delta^{15}*N),
            expression(True~delta^{15}*N),
            unname(coef(mN2)[2]), unname(coef(mN2)[1]), summary(mN2)$r.squared,
            include_outliers = FALSE),
          startRow = 41, startCol = 9)
      }
    }
  }

  if (!is.null(mdf) && nrow(mdf) > 1 && !is.null(res$Mass_C_slope)) {
    mdf[["Plot ID"]] <- mdf[["Row number"]]
    sercon_embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf, "Area All C", "International corrected d 13C/12C",
        "Mass correction - Carbon", "Area All C",
        expression(International~corrected~delta^{13}*C),
        res$Mass_C_slope, res$Mass_C_intercept, res$Mass_C_r2, excl_flag = "outlier_C"),
      startRow = 35, startCol = 21)
    sercon_embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf, "Area All N", "International corrected d 15N/14N",
        "Mass correction - Nitrogen", "Area All N",
        expression(International~corrected~delta^{15}*N),
        res$Mass_N_slope, res$Mass_N_intercept, res$Mass_N_r2, excl_flag = "outlier_N"),
      startRow = 35, startCol = 11)
    keep_m_c <- mdf[mdf$outlier_C != "Yes", , drop = FALSE]
    keep_m_n <- mdf[mdf$outlier_N != "Yes", , drop = FALSE]
    if (nrow(keep_m_c) > 1) {
      mMC2 <- lm(keep_m_c[["Mass corrected d 13C/12C"]] ~ keep_m_c[["Area All C"]])
      sercon_embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_c, "Area All C", "Mass corrected d 13C/12C",
          "Mass check - Carbon", "Area All C",
          expression(Mass~corrected~delta^{13}*C),
          unname(coef(mMC2)[2]), unname(coef(mMC2)[1]), summary(mMC2)$r.squared,
          include_outliers = FALSE),
        startRow = 56, startCol = 21)
    }
    if (nrow(keep_m_n) > 1) {
      mMN2 <- lm(keep_m_n[["Mass corrected d 15N/14N"]] ~ keep_m_n[["Area All N"]])
      sercon_embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_n, "Area All N", "Mass corrected d 15N/14N",
          "Mass check - Nitrogen", "Area All N",
          expression(Mass~corrected~delta^{15}*N),
          unname(coef(mMN2)[2]), unname(coef(mMN2)[1]), summary(mMN2)$r.squared,
          include_outliers = FALSE),
        startRow = 56, startCol = 11)
    }
    sercon_embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf, "Row", "Mass corrected d 13C/12C",
        "Drift correction - Carbon", "Row",
        expression(Mass~corrected~delta^{13}*C),
        res$Drift_C_slope, res$Drift_C_intercept, res$Drift_C_r2, excl_flag = "outlier_C"),
      startRow = 76, startCol = 21)
    sercon_embed_ggplot(wb, "Inhouse_standards",
      plot_wb_scatter(mdf, "Row", "Mass corrected d 15N/14N",
        "Drift correction - Nitrogen", "Row",
        expression(Mass~corrected~delta^{15}*N),
        res$Drift_N_slope, res$Drift_N_intercept, res$Drift_N_r2, excl_flag = "outlier_N"),
      startRow = 76, startCol = 11)
    if (nrow(keep_m_c) > 1 && "Drift corrected d 13C/12C" %in% names(mdf)) {
      mDC2 <- lm(keep_m_c[["Drift corrected d 13C/12C"]] ~ keep_m_c$Row)
      sercon_embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_c, "Row", "Drift corrected d 13C/12C",
          "Drift check - Carbon", "Row",
          expression(Drift~corrected~delta^{13}*C),
          unname(coef(mDC2)[2]), unname(coef(mDC2)[1]), summary(mDC2)$r.squared,
          include_outliers = FALSE),
        startRow = 96, startCol = 21)
    }
    if (nrow(keep_m_n) > 1 && "Drift corrected d 15N/14N" %in% names(mdf)) {
      mDN2 <- lm(keep_m_n[["Drift corrected d 15N/14N"]] ~ keep_m_n$Row)
      sercon_embed_ggplot(wb, "Inhouse_standards",
        plot_wb_scatter(keep_m_n, "Row", "Drift corrected d 15N/14N",
          "Drift check - Nitrogen", "Row",
          expression(Drift~corrected~delta^{15}*N),
          unname(coef(mDN2)[2]), unname(coef(mDN2)[1]), summary(mDN2)$r.squared,
          include_outliers = FALSE),
        startRow = 96, startCol = 11)
    }
    # CN stoichiometry plots
    if (!is.null(res$TCD_C_slope) && "µg C/cup" %in% names(mdf)) {
      keep_cn_c <- keep_m_c[!is.na(keep_m_c[["µg C/cup"]]), , drop = FALSE]
      keep_cn_n <- keep_m_n[!is.na(keep_m_n[["µg N/cup"]]), , drop = FALSE]
      if (nrow(keep_cn_c) > 0) {
        sercon_embed_ggplot(wb, "Inhouse_standards",
          plot_wb_scatter(keep_cn_c, "Area All C", "µg C/cup",
            "Correction - CN (C)", "Area All C", "µg C/cup",
            res$TCD_C_slope, 0, res$TCD_C_r2, include_outliers = FALSE),
          startRow = 35, startCol = 25)
      }
      if (nrow(keep_cn_n) > 0) {
        sercon_embed_ggplot(wb, "Inhouse_standards",
          plot_wb_scatter(keep_cn_n, "Area All N", "µg N/cup",
            "Correction - CN (N)", "Area All N", "µg N/cup",
            res$TCD_N_slope, 0, res$TCD_N_r2, include_outliers = FALSE),
          startRow = 35, startCol = 15)
      }
    }
  }

  freezePane(wb, "Samples", firstActiveRow = 2, firstActiveCol = 4)
  freezePane(wb, "International_standards", firstActiveRow = 2, firstActiveCol = 4)
  freezePane(wb, "Inhouse_standards", firstActiveRow = 2, firstActiveCol = 4)
  wb
}

