sercon_ea_ui <- function(id) {
  ns <- NS(id)
  tags$div(
    id = id,
    tags$head(tags$style(HTML(isotope_tab_css(id)))),
    h3("Sercon EA"),
    sidebarLayout(
      sidebarPanel(
        width = 3,
        fileInput(ns("file"), "Raw Sercon .xls", accept = c(".xls", ".xlsx")),
        fileInput(ns("template_1"), "Template 1 (.xlsx, optional)", accept = c(".xlsx")),
        fileInput(ns("template_2"), "Template 2 (.xlsx, optional; wells matched as AA1, BB1, …)",
                  accept = c(".xlsx")),
        checkboxInput(ns("blank_correct_n"),
                      "Blank-correct nitrogen (off = default passthrough)",
                      value = FALSE),
        outlier_sidebar_ui(ns, "C / N"),
        actionButton(ns("update"), "Apply corrections / refresh preview",
                     class = "btn-primary"),
        br(), br(),
        download_buttons_ui(ns),
        hr(),
        verbatimTextOutput(ns("flags"))
      ),
      mainPanel(
        width = 9,
        tabsetPanel(
          id = ns("main_tabs"),
          selected = "international",
          tabPanel("International standards", value = "international",
              br(),
              p("Numbers on the plots are Plot ID (tick at left). Removed standards turn red and are left out of the fit. Intl uses Blank-corrected vs True."),
              DTOutput(ns("intl_sorted_table")),
              br(),
              h4("International correction"),
              fluidRow(
                column(6, plotOutput(ns("p_intl_c"), height = "380px")),
                column(6, plotOutput(ns("p_intl_n"), height = "380px"))),
              h4("International check (outliers removed)"),
              fluidRow(
                column(6, plotOutput(ns("p_intl_check_c"), height = "380px")),
                column(6, plotOutput(ns("p_intl_check_n"), height = "380px")))
            ),
            tabPanel("Inhouse standards", value = "inhouse",
              br(),
              p("Plot numbers match the ticks at left. Mass uses Area All C/N; drift uses Row. Check plots drop outliers."),
              DTOutput(ns("mass_named_table")),
              br(),
              h4("Mass then drift correction"),
              fluidRow(
                column(6, plotOutput(ns("q_mass_c"), height = "380px")),
                column(6, plotOutput(ns("q_mass_n"), height = "380px"))),
              fluidRow(
                column(6, plotOutput(ns("q_drift_c"), height = "380px")),
                column(6, plotOutput(ns("q_drift_n"), height = "380px"))),
              h4("Mass / drift check (outliers removed)"),
              fluidRow(
                column(6, plotOutput(ns("q_mass_check_c"), height = "380px")),
                column(6, plotOutput(ns("q_mass_check_n"), height = "380px"))),
              fluidRow(
                column(6, plotOutput(ns("q_drift_check_c"), height = "380px")),
                column(6, plotOutput(ns("q_drift_check_n"), height = "380px"))),
              h4("Elemental (Area vs µg/cup)"),
              fluidRow(
                column(6, plotOutput(ns("q_cn_c"), height = "380px")),
                column(6, plotOutput(ns("q_cn_n"), height = "380px")))
            ),
            tabPanel("Samples", value = "samples",
              br(),
              p("Corrected sample values after Apply. Green = final drift-corrected N/C and C/N."),
              DTOutput(ns("sample_table"))
            ),
            tabPanel("Coefficients", value = "coefficients",
              br(), tableOutput(ns("coef_table"))
            )
          )
        )
      )
    )
}

sercon_ea_server <- function(id) {
  moduleServer(id, function(input, output, session) {
    msg_notran <- "Press Apply-corrections button first."

    observeEvent(input$file, {
      updateTabsetPanel(session, "main_tabs", selected = "international")
    })

    template1_r <- reactive({
      if (is.null(input$template_1)) return(NULL)
      load_sercon_template(input$template_1$datapath)
    })
    template2_r <- reactive({
      if (is.null(input$template_2)) return(NULL)
      load_sercon_template(input$template_2$datapath)
    })

    split_data <- reactive({
      validate(need(input$file, "Upload a raw Sercon .xls file first."))
      raw <- load_sercon_raw(input$file$datapath)
      merged <- merge_sercon_templates(raw, template1_r(), template2_r())
      format_sercon_split(merged, sercon_std_values)
    })

    # Non-blank intl / mass for tables & checkboxes
    intl_fit_base <- reactive({
      idf <- split_data()$International_df
      idf <- idf[!(idf[["Identifier 1"]] %in% Blank_ID), , drop = FALSE]
      rownames(idf) <- NULL
      if (nrow(idf) == 0) return(idf)
      # Pre-blank-correction offsets already on Measured; show Blank-True after blank step via preview
      idf[["Row number"]] <- seq_len(nrow(idf))
      idf
    })

    mass_fit_base <- reactive({
      mdf <- split_data()$Mass_df
      mdf <- mdf[!(mdf[["Identifier 1"]] %in% Blank_ID), , drop = FALSE]
      rownames(mdf) <- NULL
      if (nrow(mdf) == 0) return(mdf)
      mdf[["Row number"]] <- seq_len(nrow(mdf))
      mdf
    })

    preview <- reactive({
      sd <- split_data()
      split <- isTRUE(input$split_outliers)
      apply_sercon_corrections(
        sd$International_df, sd$Mass_df, sd$Sample_df,
        sercon_std_values,
        exclude_intl_c = pick_excl(split, input$intl_excl, input$intl_excl_c),
        exclude_intl_n = pick_excl(split, input$intl_excl, input$intl_excl_n),
        exclude_mass_c = pick_excl(split, input$mass_excl, input$mass_excl_c),
        exclude_mass_n = pick_excl(split, input$mass_excl, input$mass_excl_n),
        blank_correct_n = isTRUE(input$blank_correct_n)
      )
    })

    corrected <- eventReactive(input$update, {
      preview()
    })

    output$intl_checks <- renderUI({
      idf <- intl_fit_base()
      validate(need(nrow(idf) > 0, "No international standards in this file."))
      if (isTRUE(input$split_outliers)) {
        outlier_dual_checks_ui(session$ns, "intl_excl_c", "intl_excl_n",
                               "Intl C", "Intl N", nrow(idf), idf[["Identifier 1"]])
      } else {
        outlier_single_checks_ui(session$ns, "intl_excl", "Intl",
                                 nrow(idf), idf[["Identifier 1"]])
      }
    })

    output$mass_checks <- renderUI({
      mdf <- mass_fit_base()
      validate(need(nrow(mdf) > 0, "No inhouse standards in this file."))
      if (isTRUE(input$split_outliers)) {
        outlier_dual_checks_ui(session$ns, "mass_excl_c", "mass_excl_n",
                               "Inhouse C", "Inhouse N", nrow(mdf), mdf[["Identifier 1"]])
      } else {
        outlier_single_checks_ui(session$ns, "mass_excl", "Inhouse",
                                 nrow(mdf), mdf[["Identifier 1"]])
      }
    })

    output$intl_sorted_table <- renderDT({
      res <- preview()
      idf <- res$International_df
      validate(need(!is.null(idf) && nrow(idf) > 0, "No international standards in this file."))
      cols <- c("Plot ID", "Row", "Identifier 1", "Runname", "Area All N", "d 15N/14N",
                "True d 15N/14N", "Blank corrected d 15N/14N", "Blank corrected-TrueN",
                "Area All C", "d 13C/12C", "True d 13C/12C",
                "Blank corrected d 13C/12C", "Blank corrected-TrueC")
      if (!"Plot ID" %in% names(idf) && "Row number" %in% names(idf))
        idf[["Plot ID"]] <- idf[["Row number"]]
      if (!"Plot ID" %in% names(idf))
        idf[["Plot ID"]] <- seq_len(nrow(idf))
      show <- idf[order(idf[["Identifier 1"]], idf$Row), intersect(cols, names(idf)), drop = FALSE]
      style_corr_dt(show, c("Blank corrected-TrueN", "Blank corrected-TrueC"))
    })

    output$mass_named_table <- renderDT({
      res <- preview()
      mdf <- res$Mass_df
      validate(need(!is.null(mdf) && nrow(mdf) > 0, "No inhouse standards in this file."))
      if (!"Plot ID" %in% names(mdf) && "Row number" %in% names(mdf))
        mdf[["Plot ID"]] <- mdf[["Row number"]]
      if (!"Plot ID" %in% names(mdf))
        mdf[["Plot ID"]] <- seq_len(nrow(mdf))
      cols <- c("Plot ID", "Row", "Identifier 1", "Runname",
                "Area All N", "d 15N/14N", "True d 15N/14N",
                "Blank corrected d 15N/14N", "Blank corrected-TrueN",
                "Area All C", "d 13C/12C", "True d 13C/12C",
                "Blank corrected d 13C/12C", "Blank corrected-TrueC")
      show <- mdf[, intersect(cols, names(mdf)), drop = FALSE]
      rn <- as.character(show[["Identifier 1"]])
      show2 <- show[, setdiff(names(show), "Identifier 1"), drop = FALSE]
      dt <- datatable(show2, rownames = rn, options = list(
        scrollX = TRUE, pageLength = 100,
        lengthMenu = list(c(25, 50, 100, -1), c("25", "50", "100", "All"))
      ))
      for (col in intersect(c("Blank corrected-TrueN", "Blank corrected-TrueC"), names(show2))) {
        dt <- formatStyle(dt, col, backgroundColor = "#C6EFCE")
      }
      dt
    })

    # ---- International plots ----
    output$p_intl_c <- renderPlot({
      res <- preview(); idf <- res$International_df
      validate(need(!is.null(idf) && nrow(idf) > 0, "No international standards."))
      plot_std_scatter(idf, "Blank corrected d 13C/12C", "True d 13C/12C",
        "International - Carbon", "Blank corr d13C", "True d13C",
        exclude = pick_excl(input$split_outliers, input$intl_excl, input$intl_excl_c),
        slope = res$C_slope, intercept = res$C_intercept, r2 = res$C_r2)
    })
    output$p_intl_n <- renderPlot({
      res <- preview(); idf <- res$International_df
      validate(need(!is.null(idf) && nrow(idf) > 0, "No international standards."))
      plot_std_scatter(idf, "Blank corrected d 15N/14N", "True d 15N/14N",
        "International - Nitrogen", "Blank corr d15N", "True d15N",
        exclude = pick_excl(input$split_outliers, input$intl_excl, input$intl_excl_n),
        slope = res$N_slope, intercept = res$N_intercept, r2 = res$N_r2)
    })
    output$p_intl_check_c <- renderPlot({
      res <- preview(); idf <- res$International_df
      validate(need(!is.null(idf) && nrow(idf) > 0, "No international standards."))
      validate(need(isTRUE(res$has_C_anchors), "Need NBS18 + CAFFEINE for C correction."))
      keep <- idf[idf$outlier_C != "Yes", , drop = FALSE]
      validate(need(nrow(keep) > 1, "Not enough standards left after removals."))
      plot_std_scatter(keep, "International corrected d 13C/12C", "True d 13C/12C",
        "International check - Carbon", "Intl corr d13C", "True d13C")
    })
    output$p_intl_check_n <- renderPlot({
      res <- preview(); idf <- res$International_df
      validate(need(!is.null(idf) && nrow(idf) > 0, "No international standards."))
      validate(need(isTRUE(res$has_N_anchors), "Need N2 + CAFFEINE for N correction."))
      keep <- idf[idf$outlier_N != "Yes", , drop = FALSE]
      validate(need(nrow(keep) > 1, "Not enough standards left after removals."))
      plot_std_scatter(keep, "International corrected d 15N/14N", "True d 15N/14N",
        "International check - Nitrogen", "Intl corr d15N", "True d15N")
    })

    # ---- Inhouse plots ----
    output$q_mass_c <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
      validate(need("International corrected d 13C/12C" %in% names(mdf),
                    "Need international standards to fit the correction."))
      plot_std_scatter(mdf, "Area All C", "International corrected d 13C/12C",
        "Mass correction - Carbon", "Area All C", "Intl corr d13C",
        exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_c),
        slope = res$Mass_C_slope, intercept = res$Mass_C_intercept, r2 = res$Mass_C_r2)
    })
    output$q_mass_n <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
      plot_std_scatter(mdf, "Area All N", "International corrected d 15N/14N",
        "Mass correction - Nitrogen", "Area All N", "Intl corr d15N",
        exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_n),
        slope = res$Mass_N_slope, intercept = res$Mass_N_intercept, r2 = res$Mass_N_r2)
    })
    output$q_drift_c <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
      validate(need("Mass corrected d 13C/12C" %in% names(mdf),
                    "Need mass correction first."))
      plot_std_scatter(mdf, "Row", "Mass corrected d 13C/12C",
        "Drift correction - Carbon", "Row", "Mass corr d13C",
        exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_c),
        slope = res$Drift_C_slope, intercept = res$Drift_C_intercept, r2 = res$Drift_C_r2)
    })
    output$q_drift_n <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
      plot_std_scatter(mdf, "Row", "Mass corrected d 15N/14N",
        "Drift correction - Nitrogen", "Row", "Mass corr d15N",
        exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_n),
        slope = res$Drift_N_slope, intercept = res$Drift_N_intercept, r2 = res$Drift_N_r2)
    })
    output$q_mass_check_c <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
      keep <- mdf[mdf$outlier_C != "Yes", , drop = FALSE]
      validate(need(nrow(keep) > 1, "Not enough inhouse left after removals."))
      plot_std_scatter(keep, "Area All C", "Mass corrected d 13C/12C",
        "Mass check - Carbon", "Area All C", "Mass corr d13C")
    })
    output$q_mass_check_n <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
      keep <- mdf[mdf$outlier_N != "Yes", , drop = FALSE]
      validate(need(nrow(keep) > 1, "Not enough inhouse left after removals."))
      plot_std_scatter(keep, "Area All N", "Mass corrected d 15N/14N",
        "Mass check - Nitrogen", "Area All N", "Mass corr d15N")
    })
    output$q_drift_check_c <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
      keep <- mdf[mdf$outlier_C != "Yes", , drop = FALSE]
      validate(need(nrow(keep) > 1 && "Drift corrected d 13C/12C" %in% names(keep),
                    "Not enough inhouse left after removals."))
      plot_std_scatter(keep, "Row", "Drift corrected d 13C/12C",
        "Drift check - Carbon", "Row", "Drift corr d13C")
    })
    output$q_drift_check_n <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      validate(need(!is.null(mdf) && nrow(mdf) > 1, "Not enough inhouse standards."))
      keep <- mdf[mdf$outlier_N != "Yes", , drop = FALSE]
      validate(need(nrow(keep) > 1, "Not enough inhouse left after removals."))
      plot_std_scatter(keep, "Row", "Drift corrected d 15N/14N",
        "Drift check - Nitrogen", "Row", "Drift corr d15N")
    })
    output$q_cn_c <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      validate(need(!is.null(mdf) && nrow(mdf) > 1 && "µg C/cup" %in% names(mdf),
                    "No elemental C calibration."))
      plot_std_scatter(mdf, "Area All C", "µg C/cup",
        "Elemental - Carbon", "Area All C", "µg C/cup",
        exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_c), through_origin = TRUE)
    })
    output$q_cn_n <- renderPlot({
      res <- preview(); mdf <- res$Mass_df
      validate(need(!is.null(mdf) && nrow(mdf) > 1 && "µg N/cup" %in% names(mdf),
                    "No elemental N calibration."))
      plot_std_scatter(mdf, "Area All N", "µg N/cup",
        "Elemental - Nitrogen", "Area All N", "µg N/cup",
        exclude = pick_excl(input$split_outliers, input$mass_excl, input$mass_excl_n), through_origin = TRUE)
    })

    output$coef_table <- renderTable({
      res <- corrected()
      validate(need(!is.null(res$Mass_C_slope) || !is.null(res$C_slope) || !is.null(res$N_slope),
                    msg_notran))
      build_sercon_coef_df(res)
    }, digits = 10)

    output$sample_table <- renderDT({
      res <- corrected()
      sdf <- res$Sample_df
      validate(need(!is.null(sdf) && nrow(sdf) > 0, msg_notran))
      sdf <- pick_cols(sdf, sercon_export_sample_cols)
      style_corr_dt(sdf, c(
        "Drift corrected d 15N/14N",
        "Drift corrected d 13C/12C",
        "C/N"),
        red_col = "Possibly bad sample")
    })

    output$flags <- renderText({
      sd <- tryCatch(split_data(), error = function(e) NULL)
      if (is.null(sd)) return("Upload a raw file to begin.")
      msgs <- character(0)
      n_intl <- sum(!(sd$International_df[["Identifier 1"]] %in% Blank_ID))
      n_mass <- sum(!(sd$Mass_df[["Identifier 1"]] %in% Blank_ID))
      n_samp <- nrow(sd$Sample_df)
      msgs <- c(msgs, paste0("Intl standards (excl. blank): ", n_intl))
      msgs <- c(msgs, paste0("Inhouse GEL A (excl. blank): ", n_mass))
      msgs <- c(msgs, paste0("Sample rows: ", n_samp))
      if (is.null(template1_r()) && is.null(template2_r()))
        msgs <- c(msgs, "No weighing template loaded (optional).")
      paste(msgs, collapse = "\n")
    })

    output$download_wb <- downloadHandler(
      filename = function() {
        base <- if (!is.null(input$file)) tools::file_path_sans_ext(input$file$name) else "Corrected"
        paste0(base, "_corrected.xlsx")
      },
      contentType = xlsx_content_type,
      content = function(file) {
        res <- corrected()
        coef_df <- tryCatch(build_sercon_coef_df(res), error = function(e) {
          data.frame(Correction = character(0), Slope = numeric(0),
                     Intercept = numeric(0), R_squared = numeric(0))
        })
        wb <- build_sercon_workbook(res, coef_df, template1_r(), template2_r())
        on.exit(sercon_clear_embed_tmp(), add = TRUE)
        saveWorkbook(wb, file, overwrite = TRUE)
      }
    )

    output$download_csv <- downloadHandler(
      filename = function() {
        base <- if (!is.null(input$file)) tools::file_path_sans_ext(input$file$name) else "Corrected"
        paste0(base, "_corrected_csv.zip")
      },
      contentType = csv_zip_content_type,
      content = function(file) {
        res <- corrected()
        exp <- format_sercon_export_dfs(res)
        coef_df <- tryCatch(build_sercon_coef_df(res), error = function(e) {
          data.frame(Correction = character(0), Slope = numeric(0),
                     Intercept = numeric(0), R_squared = numeric(0))
        })
        sheets <- list(
          Samples = exp$Sample_df,
          International_standards = exp$International_df,
          Inhouse_standards = exp$Mass_df,
          Coefficients = coef_df
        )
        write_sheets_csv_zip(sheets, file)
      }
    )
  })
}

