ui <- fluidPage(
  tags$head(tags$style(HTML("
    .instrument-chooser {
      max-width: 720px; margin: 1.5rem auto; padding: 1.25rem 1.75rem;
      border: 1px solid #ddd; border-radius: 8px; background: #fafafa;
    }
    .instrument-chooser h3 { margin-top: 0; }
    .instrument-bar {
      display: flex; align-items: center; gap: 1rem; flex-wrap: wrap;
      margin-bottom: 0.5rem;
    }
  "))),
  titlePanel("Isotope lab correction"),
  conditionalPanel(
    condition = "input.instrument == null || input.instrument === ''",
    tags$div(class = "instrument-chooser",
      h3("Choose instrument / workflow"),
      p("Same operator flow as the R notebooks: International → Inhouse → Samples / Coefficients, then download the corrected workbook."),
      radioButtons("instrument", NULL,
        choiceNames = list(
          "Thermo GasBench (C / O)",
          "Thermo EA (C / N + Flash TCD)",
          "Sercon EA (C / N + weighing templates)"
        ),
        choiceValues = c("gb", "ea", "sercon"),
        selected = character(0)
      )
    )
  ),
  conditionalPanel(
    condition = "input.instrument === 'gb' || input.instrument === 'ea' || input.instrument === 'sercon'",
    tags$div(class = "instrument-bar",
      actionLink("back_home", "← Change instrument"),
      textOutput("instrument_label", inline = TRUE)
    ),
    hr()
  ),
  conditionalPanel(
    condition = "input.instrument === 'gb'",
    thermo_gb_ui("gb")
  ),
  conditionalPanel(
    condition = "input.instrument === 'ea'",
    thermo_ea_ui("ea")
  ),
  conditionalPanel(
    condition = "input.instrument === 'sercon'",
    sercon_ea_ui("sercon")
  )
)

server <- function(input, output, session) {
  # Desktop launcher sets this so closing the browser tab stops R (and the terminal).
  if (isTRUE(getOption("isotope_app.quit_on_close", FALSE))) {
    session$onSessionEnded(function() stopApp())
  }

  if (exists("thermo_gb_server", mode = "function")) thermo_gb_server("gb")
  if (exists("thermo_ea_server", mode = "function")) thermo_ea_server("ea")
  if (exists("sercon_ea_server", mode = "function")) sercon_ea_server("sercon")

  output$instrument_label <- renderText({
    switch(input$instrument %||% "",
      gb = "Thermo GasBench",
      ea = "Thermo EA",
      sercon = "Sercon EA",
      ""
    )
  })

  observeEvent(input$back_home, {
    updateRadioButtons(session, "instrument", selected = character(0))
  })
}

shinyApp(ui, server)

